-- =====================================================================
-- 177: 16 fármacos novos do QUADRO 2 do Anexo 7 do Prontuário
--      (acenocumarol a pimozida) + perfis completos
-- ---------------------------------------------------------------------
-- Objetivo: aumentar o catálogo com os 16 fármacos identificados na
-- análise dos anexos (Lote A) — fármacos com interações documentadas no
-- QUADRO 2 (Anexo 7) que ainda não existem na BD. Padrão de perfil
-- completo (mesmas 5 tabelas da 171/174):
--   * drug_profiles (overview público/pro, indicações, efeitos,
--     precauções);
--   * drug_pharmacology (mecanismo, metabolismo, absorção, meia-vida);
--   * drug_pregnancy_info (sempre preenchida);
--   * drug_disease_interactions (só as documentadas);
--   * drug_food_interactions (só as documentadas).
--
-- Fontes: rótulos aprovados FDA/DailyMed (NIH/NLM) — setIDs validados a
-- 2026-08-17 via API v2 (spls.json?drug_name=) + drugInfo.cfm; secções
-- 4/5/7/8/12 lidas. Para os 2 sem rótulo DailyMed:
--   * Acenocumarol  — EMC-UK Sinthrome 1 mg (product/2058) +
--                     Prontuário 4.3.1.2 (Anticoagulantes orais);
--   * Indacaterol   — Prontuário 5.1.1 (Agonistas adrenérgicos beta) +
--                     QUADRO 2 do Anexo 7 (CYP3A4/P-gp).
--
-- Idempotente: ON CONFLICT (drug_id) DO NOTHING (e (drug_id,
-- condition_slug)/(drug_id, entity_slug) nas dimensões). Aplicar na
-- ordem: fármacos (177) → perfis/farmacologia → dimensões. Reaplicar é
-- seguro.
-- =====================================================================

-- =====================================================================
-- 1. Fármacos novos (16) — padrão 7.3 (sort_order a partir de 210)
-- =====================================================================
INSERT INTO public.drugs (slug, name_pt, name_en, class_pt, class_en, aliases, status, sort_order)
VALUES
  ('acenocumarol', 'Acenocumarol', 'Acenocoumarol', 'Anticoagulante oral (derivado cumarínico)', 'Oral anticoagulant (coumarin derivative)', ARRAY['Acenocumarol', 'Sintrom', 'Sinthrome'], 'published', 210),
  ('eslicarbazepina', 'Eslicarbazepina', 'Eslicarbazepine', 'Antiepilético (bloqueador dos canais de sódio)', 'Antiepileptic (sodium channel blocker)', ARRAY['Eslicarbazepina', 'Acetato de eslicarbazepina', 'Zebinix'], 'published', 211),
  ('cimetidina', 'Cimetidina', 'Cimetidine', 'Antagonista dos recetores H2 (antiulceroso)', 'H2-receptor antagonist (antiulcer)', ARRAY['Cimetidina', 'Tagamet'], 'published', 212),
  ('cloranfenicol', 'Cloranfenicol', 'Chloramphenicol', 'Antibiótico (anfenicol)', 'Antibiotic (amphenicol)', ARRAY['Cloranfenicol', 'Cloromicetina'], 'published', 213),
  ('dissulfiram', 'Dissulfiram', 'Disulfiram', 'Anti-alcoólico (inibidor da aldeído desidrogenase)', 'Alcohol deterrent (aldehyde dehydrogenase inhibitor)', ARRAY['Dissulfiram', 'Antabuse'], 'published', 214),
  ('ertapenem', 'Ertapenem', 'Ertapenem', 'Antibiótico carbapenemo', 'Carbapenem antibiotic', ARRAY['Ertapenem', 'Invanz'], 'published', 215),
  ('indacaterol', 'Indacaterol', 'Indacaterol', 'Broncodilatador (agonista beta-2 adrenérgico de longa duração)', 'Bronchodilator (long-acting beta-2 adrenergic agonist)', ARRAY['Indacaterol', 'Onbrez', 'Hirobriz'], 'published', 216),
  ('ivabradina', 'Ivabradina', 'Ivabradine', 'Inibidor do canal If (bradicardizante)', 'If channel inhibitor (heart rate lowering)', ARRAY['Ivabradina', 'Procoralan', 'Corlanor'], 'published', 217),
  ('levodopa', 'Levodopa', 'Levodopa', 'Antiparkinsónico (precursor da dopamina)', 'Antiparkinsonian (dopamine precursor)', ARRAY['Levodopa', 'L-dopa'], 'published', 218),
  ('ticagrelor', 'Ticagrelor', 'Ticagrelor', 'Antiagregante plaquetário (inibidor reversível do P2Y12)', 'Antiplatelet (reversible P2Y12 inhibitor)', ARRAY['Ticagrelor', 'Brilinta'], 'published', 219),
  ('diltiazem', 'Diltiazem', 'Diltiazem', 'Bloqueador dos canais de cálcio (benzotiazepina)', 'Calcium channel blocker (benzothiazepine)', ARRAY['Diltiazem', 'Tiazac'], 'published', 220),
  ('verapamilo', 'Verapamilo', 'Verapamil', 'Bloqueador dos canais de cálcio (fenilalquilamina)', 'Calcium channel blocker (phenylalkylamine)', ARRAY['Verapamilo', 'Isoptin'], 'published', 221),
  ('tacrolimus', 'Tacrolimus', 'Tacrolimus', 'Imunossupressor (inibidor da calcineurina)', 'Immunosuppressant (calcineurin inhibitor)', ARRAY['Tacrolimus', 'Prograf'], 'published', 222),
  ('sirolimus', 'Sirolimus', 'Sirolimus', 'Imunossupressor (inibidor do mTOR)', 'Immunosuppressant (mTOR inhibitor)', ARRAY['Sirolimus', 'Rapamune'], 'published', 223),
  ('micofenolato', 'Micofenolato', 'Mycophenolate', 'Imunossupressor (inibidor da IMPDH)', 'Immunosuppressant (IMPDH inhibitor)', ARRAY['Micofenolato', 'Micofenolato de mofetilo', 'CellCept'], 'published', 224),
  ('pimozida', 'Pimozida', 'Pimozide', 'Antipsicótico (neuroléptico difenilbutilpiperidina)', 'Antipsychotic (diphenylbutylpiperidine neuroleptic)', ARRAY['Pimozida', 'Orap'], 'published', 225);

-- =====================================================================
-- 2. Perfis (drug_profiles) — padrão 7.6
-- =====================================================================
INSERT INTO public.drug_profiles
  (drug_id, overview_public_pt, overview_public_en, overview_pro_pt, overview_pro_en,
   indications_pt, indications_en, side_effects_pt, side_effects_en,
   precautions_pt, precautions_en, source_pt, source_en, status)
SELECT d.id, v.overview_public_pt, v.overview_public_en, v.overview_pro_pt, v.overview_pro_en,
       v.indications_pt, v.indications_en, v.side_effects_pt, v.side_effects_en,
       v.precautions_pt, v.precautions_en, v.source_pt, v.source_en, 'published'
FROM public.drugs d
JOIN (VALUES
  ('acenocumarol',
   E'O acenocumarol é um anticoagulante oral usado para prevenir e tratar coágulos no sangue (trombose venosa, embolia pulmonar) e para prevenir o AVC em pessoas com fibrilhação auricular. Atua reduzindo a produção dos fatores de coagulação no fígado, dependentes da vitamina K.',
   E'Acenocoumarol is an oral anticoagulant used to prevent and treat blood clots (venous thrombosis, pulmonary embolism) and to prevent stroke in people with atrial fibrillation. It works by reducing the liver production of vitamin K-dependent clotting factors.',
   E'Anticoagulante oral derivado da 4-hidroxicumarina (com a varfarina, é o representante dos cumarínicos). Reduz a síntese hepática dos fatores II, VII, IX e X da coagulação por antagonismo da vitamina K (fitomenadiona); sem efeito anticoagulante in vitro. O efeito só se torna aparente após a depleção plasmática dos fatores (2-3 dias após o início); a heparina é o anticoagulante de escolha quando se necessita de efeito imediato. Controlo pelo INR (alvo 2,0-3,0 conforme indicação; 3,0-3,5 em próteses mecânicas). O acenocumarol utiliza-se com menos frequência que a varfarina (Prontuário 4.3.1.2).',
   E'Oral anticoagulant derived from 4-hydroxycoumarin (with warfarin, it is the representative of the coumarins). Reduces the hepatic synthesis of coagulation factors II, VII, IX and X by antagonising vitamin K (phytonadione); no in vitro anticoagulant effect. The effect only becomes apparent after plasma depletion of the factors (2-3 days after start); heparin is the anticoagulant of choice when an immediate effect is needed. Monitored by INR (target 2.0-3.0 depending on indication; 3.0-3.5 in mechanical valves). Acenocoumarol is used less often than warfarin (Prontuário 4.3.1.2).',
   E'• Tratamento da trombose venosa profunda e do embolismo pulmonar (Prontuário 4.3.1.2)\\n• Prevenção de tromboembolismo em doentes com fibrilhação auricular com risco de embolização, próteses valvulares cardíacas, cirurgia complicada ou imobilização prolongada (ex: idoso após cirurgia ortopédica) e no enfarte agudo do miocárdio',
   E'• Treatment of deep vein thrombosis and pulmonary embolism (Prontuário 4.3.1.2)\\n• Prevention of thromboembolism in patients with atrial fibrillation at risk of embolisation, prosthetic heart valves, complicated surgery or prolonged immobilisation (e.g. elderly after orthopaedic surgery) and in acute myocardial infarction',
   E'• Hemorragia (reação adversa mais comum, com tradução clínica diversificada — de equimose mínima a hemorragia grave potencialmente fatal)\\n• Erupção cutânea, alopécia\\n• Necrose e/ou gangrena de pele e outros tecidos (2-10 dias após início), com cor arroxeada das faces plantares/laterais dos dedos\\n• Disfunção hepática, náuseas, vómitos, pancreatite, queda do hematócrito\\n• Reações de hipersensibilidade — Prontuário 4.3.1.2',
   E'• Haemorrhage (the most common adverse reaction, with varied clinical expression — from minimal ecchymosis to severe, potentially fatal bleeding)\\n• Skin rash, alopecia\\n• Skin and other tissue necrosis and/or gangrene (2-10 days after start), with purplish discolouration of the plantar and lateral surfaces of the toes\\n• Hepatic dysfunction, nausea, vomiting, pancreatitis, drop in haematocrit\\n• Hypersensitivity reactions — Prontuário 4.3.1.2',
   E'• Contraindicado quando coexiste risco acrescido de hemorragia ou necrose, infeções graves, doença cerebrovascular, oclusão arterial periférica e endocardite bacteriana (Prontuário 4.3.1.2)\\n• Contraindicado no 1.º trimestre da gravidez (teratogénico) e nas últimas semanas (risco de hemorragia fetal ou placentar), na diátese hemorrágica e na não adesão à terapêutica\\n• EMC-UK (Sinthrome 4.4): precaução na insuficiência hepática ligeira a moderada e na insuficiência renal ligeira a moderada (acumulação de metabolitos); nefropatia associada a anticoagulantes — monitorizar função renal\\n• Monitorizar INR: diário ou em dias alternados até atingir e manter 2 dias consecutivos no nível útil; depois 2-3 vezes/semana durante 1-2 semanas; 1 vez/semana e, estável, com intervalos de 8-12 semanas (4.3.1.2)',
   E'• Contraindicated when there is an increased risk of bleeding or necrosis, severe infections, cerebrovascular disease, peripheral arterial occlusion and bacterial endocarditis (Prontuário 4.3.1.2)\\n• Contraindicated in the first trimester of pregnancy (teratogenic) and in the last weeks (risk of fetal or placental haemorrhage), in haemorrhagic diathesis and in non-adherence to therapy\\n• EMC-UK (Sinthrome 4.4): caution in mild to moderate hepatic impairment and mild to moderate renal impairment (metabolite accumulation); anticoagulant-related nephropathy — monitor renal function\\n• Monitor INR: daily or on alternate days until the useful level is reached and maintained for 2 consecutive days; then 2-3 times/week for 1-2 weeks; once weekly and, if stable, at 8-12 week intervals (4.3.1.2)',
   'EMC-UK — Sinthrome 1 mg Tablets SmPC (sections 4.3/4.4): https://www.medicines.org.uk/emc/product/2058 ; Prontuário Terapêutico do INFARMED (11.ª ed., 2012) — Anticoagulantes orais, 4.3.1.2',
   'EMC-UK — Sinthrome 1 mg Tablets SmPC (sections 4.3/4.4): https://www.medicines.org.uk/emc/product/2058 ; Prontuário Terapêutico do INFARMED (11th ed., 2012) — Oral anticoagulants, 4.3.1.2'),

  ('eslicarbazepina',
   E'A eslicarbazepina é um medicamento antiepilético usado, em associação, no tratamento das crises parciais (focais) em adultos e crianças a partir dos 4 anos. Reduz a atividade elétrica anormal no cérebro que causa as crises.',
   E'Eslicarbazepine is an antiepileptic medicine used, in combination, to treat partial-onset (focal) seizures in adults and children aged 4 years and older. It reduces the abnormal electrical activity in the brain that causes seizures.',
   E'Antiepilético: é extensamente convertido em eslicarbazepina, o metabolito ativo; o mecanismo anticonvulsivante envolve a inibição dos canais de sódio dependentes de voltagem (rótulo FDA 12.1). A eslicarbazepina inibe o CYP2C19 e induz o CYP3A4 — relevante para interações (7.2/7.3).',
   E'Antiepileptic: extensively converted to eslicarbazepine, the active metabolite; the anticonvulsant mechanism is thought to involve inhibition of voltage-gated sodium channels (FDA label 12.1). Eslicarbazepine inhibits CYP2C19 and induces CYP3A4 — relevant for interactions (7.2/7.3).',
   E'• Tratamento das crises parciais (focais) em doentes com 4 ou mais anos (rótulo FDA INDICATIONS AND USAGE)',
   E'• Treatment of partial-onset (focal) seizures in patients 4 years of age and older (FDA label INDICATIONS AND USAGE)',
   E'• Risco de pensamentos/comportamentos suicidas (classe dos antiepiléticos — 5.1)\\n• Tonturas, sonolência, cefaleias, náuseas, diplopia, visão turva, ataxia (reações comuns)\\n• Hiponatremia (risco acrescido em idosos e em uso de diuréticos)\\n• Reações cutâneas graves (SJS/TEN) e DRESS — suspender perante erupção sem causa identificada (5.2/5.4)\\n• Anafilaxia e angioedema (5.3)',
   E'• Risk of suicidal thoughts/behaviour (antiepileptic class — 5.1)\\n• Dizziness, somnolence, headache, nausea, diplopia, blurred vision, ataxia (common reactions)\\n• Hyponatraemia (increased risk in elderly and with diuretics)\\n• Severe skin reactions (SJS/TEN) and DRESS — discontinue upon unexplained rash (5.2/5.4)\\n• Anaphylaxis and angioedema (5.3)',
   E'• Contraindicada em doentes com hipersensibilidade à eslicarbazepina ou à oxcarbazepina (CONTRAINDICATIONS)\\n• Os antiepiléticos aumentam o risco de pensamentos ou comportamentos suicidas em qualquer indicação — monitorizar depressão, alterações de humor ou comportamento (5.1)\\n• Monitorizar sódio sérico, sobretudo em idosos e com diuréticos (5.6)\\n• Evitar a suspensão abrupta (risco de aumento da frequência das crises); retirar gradualmente (5.9)',
   E'• Contraindicated in patients with hypersensitivity to eslicarbazepine or oxcarbazepine (CONTRAINDICATIONS)\\n• Antiepileptics increase the risk of suicidal thoughts or behaviour in any indication — monitor for depression, mood or behaviour changes (5.1)\\n• Monitor serum sodium, especially in the elderly and with diuretics (5.6)\\n• Avoid abrupt discontinuation (risk of increased seizure frequency); withdraw gradually (5.9)',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Eslicarbazepina (JUBILANT CADISTA PHARMACEUTICALS INC.): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=22d08671-ac0d-4e3d-8195-929bbb021125',
   'DailyMed/FDA (NIH/NLM) — approved Eslicarbazepine label (JUBILANT CADISTA PHARMACEUTICALS INC.): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=22d08671-ac0d-4e3d-8195-929bbb021125'),

  ('cimetidina',
   E'A cimetidina é um medicamento que reduz a acidez do estômago, usado no tratamento da úlcera do estômago e do duodeno, do refluxo gastroesofágico e de condições em que o estômago produz ácido em excesso. Também está disponível sem receita em doses baixas para a azia ocasional.',
   E'Cimetidine is a medicine that reduces stomach acid, used to treat stomach and duodenal ulcers, gastro-oesophageal reflux disease and conditions in which the stomach produces too much acid. It is also available over the counter in low doses for occasional heartburn.',
   E'Antagonista dos recetores H2 da histamina nas células parietais gástricas: reduz a secreção ácida basal e estimulada (noturna e após refeições), incluindo a secreção por estímulos alimentares, histamínicos e gastrínicos. Inibidor clássico das enzimas do citocromo P450 (sobretudo CYP1A2, CYP2C9, CYP2D6 e CYP3A4) — base de numerosas interações farmacocinéticas (rótulo FDA PRECAUTIONS/Drug Interactions; Prontuário 6.2.2.2).',
   E'H2-receptor antagonist of histamine at gastric parietal cells: reduces basal and stimulated acid secretion (nocturnal and post-meal), including secretion by food, histamine and gastrin stimuli. Classic inhibitor of cytochrome P450 enzymes (mainly CYP1A2, CYP2C9, CYP2D6 and CYP3A4) — the basis of numerous pharmacokinetic interactions (FDA label PRECAUTIONS/Drug Interactions; Prontuário 6.2.2.2).',
   E'• Tratamento de curta duração da úlcera duodenal ativa (a maioria cicatriza em 4 semanas)\\n• Úlcera gástrica benigna, doença de refluxo gastroesofágico com esofagite erosiva (até 12 semanas)\\n• Condições hipersecretoras patológicas (síndrome de Zollinger-Ellison)\\n• Azia ocasional (doses baixas OTC) — rótulo FDA INDICATIONS AND USAGE',
   E'• Short-term treatment of active duodenal ulcer (most heal within 4 weeks)\\n• Benign gastric ulcer, gastro-oesophageal reflux disease with erosive oesophagitis (up to 12 weeks)\\n• Pathological hypersecretory conditions (Zollinger-Ellison syndrome)\\n• Occasional heartburn (low OTC doses) — FDA label INDICATIONS AND USAGE',
   E'• Diarreia, tonturas, sonolência, cefaleias (reações comuns)\\n• Ginecomastia, hiperprolactinemia (uso prolongado/doses altas)\\n• Confusão mental/estados confusionais (idosos, doença hepática ou renal — reversível com a suspensão)\\n• Arritmias e hipotensão (após administração IV rápida em bolus)\\n• Casos raros de bradicardia, bloqueio AV e paragem cardíaca (IV) — rótulo FDA PRECAUTIONS/ADVERSE REACTIONS',
   E'• Diarrhoea, dizziness, somnolence, headache (common reactions)\\n• Gynaecomastia, hyperprolactinaemia (long-term use/high doses)\\n• Mental confusion/confusional states (elderly, hepatic or renal disease — reversible on discontinuation)\\n• Arrhythmias and hypotension (after rapid IV bolus administration)\\n• Rare cases of bradycardia, AV block and cardiac arrest (IV) — FDA label PRECAUTIONS/ADVERSE REACTIONS',
   E'• Contraindicada em doentes com hipersensibilidade à cimetidina (CONTRAINDICATIONS)\\n• A resposta sintomática não exclui a presença de malignidade gástrica — vigiar doentes com úlcera gástrica (PRECAUTIONS)\\n• Reduzir a dose na insuficiência renal grave (300 mg a cada 12 h; pode aumentar para 8 h com precaução); na insuficiência hepática associada, reduzir ainda mais (DOSAGE AND ADMINISTRATION)\\n• Usar com precaução em idosos e doentes com doença hepática/renal (confusão mental)',
   E'• Contraindicated in patients with hypersensitivity to cimetidine (CONTRAINDICATIONS)\\n• Symptomatic response does not preclude the presence of gastric malignancy — follow gastric ulcer patients (PRECAUTIONS)\\n• Reduce dose in severe renal impairment (300 mg every 12 h; may increase to every 8 h with caution); reduce further when hepatic impairment is also present (DOSAGE AND ADMINISTRATION)\\n• Use with caution in the elderly and in hepatic/renal disease (mental confusion)',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Cimetidina (MYLAN PHARMACEUTICALS INC.): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=06c0a509-026f-44e0-9975-a94a8de51d43',
   'DailyMed/FDA (NIH/NLM) — approved Cimetidine label (MYLAN PHARMACEUTICALS INC.): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=06c0a509-026f-44e0-9975-a94a8de51d43'),

  ('cloranfenicol',
   E'O cloranfenicol é um antibiótico de largo espetro, reservado para infeções graves em que outros antibióticos menos perigosos não são eficazes ou estão contraindicados. Pode causar efeitos adversos graves na medula óssea, por isso o seu uso é limitado e vigiado.',
   E'Chloramphenicol is a broad-spectrum antibiotic reserved for serious infections in which other, less dangerous antibiotics are ineffective or contraindicated. It can cause serious bone marrow adverse effects, so its use is limited and supervised.',
   E'Antibiótico anfenicol bacteriostático de largo espetro: inibe a síntese proteica bacteriana por ligação à subunidade 50S do ribossoma. Uso restrito a infeções graves para as quais fármacos menos potencialmente perigosos são ineficazes ou contraindicados (meningite, tifóide, rickettsioses, entre outras). Risco de depressão da medula óssea (anemia aplástica idiosincrática, potencialmente fatal e irreversível) e síndrome do recém-nascido cinzento (Gray syndrome) em neonatos (rótulo FDA WARNINGS/ADVERSE REACTIONS).',
   E'Amphenicol bacteriostatic broad-spectrum antibiotic: inhibits bacterial protein synthesis by binding to the 50S ribosomal subunit. Use restricted to serious infections for which less potentially dangerous drugs are ineffective or contraindicated (meningitis, typhoid fever, rickettsioses, among others). Risk of bone marrow depression (idiosyncratic aplastic anaemia, potentially fatal and irreversible) and Gray syndrome in neonates (FDA label WARNINGS/ADVERSE REACTIONS).',
   E'• Infeções graves causadas por bactérias suscetíveis (Salmonella typhi, Haemophilus influenzae, rickettsias, entre outras) quando antibióticos menos perigosos são ineficazes ou contraindicados (rótulo FDA INDICATIONS AND USAGE)',
   E'• Serious infections caused by susceptible bacteria (Salmonella typhi, Haemophilus influenzae, rickettsiae, among others) when less dangerous antibiotics are ineffective or contraindicated (FDA label INDICATIONS AND USAGE)',
   E'• Depressão da medula óssea: anemia aplástica idiosincrática (rara, grave, irreversível) e mielossupressão dose-dependente (5)\\n• Síndrome do recém-nascido cinzento (Gray syndrome) em neonatos/prematuros — distensão abdominal, cianose, colapso vascular (6)\\n• Reações de hipersensibilidade (febre, erupções, anafilaxia)\\n• Neuropatia periférica e neurite ótica (uso prolongado)\\n• Náuseas, vómitos, diarreia, glossite — rótulo FDA ADVERSE REACTIONS',
   E'• Bone marrow depression: idiosyncratic aplastic anaemia (rare, severe, irreversible) and dose-dependent myelosuppression (5)\\n• Gray syndrome in neonates/premature infants — abdominal distension, cyanosis, vascular collapse (6)\\n• Hypersensitivity reactions (fever, rashes, anaphylaxis)\\n• Peripheral neuropathy and optic neuritis (long-term use)\\n• Nausea, vomiting, diarrhoea, glossitis — FDA label ADVERSE REACTIONS',
   E'• Contraindicado em doentes com história de hipersensibilidade ou reação tóxica prévia; não usar em infeções triviais, constipações, gripe, infeções da garganta ou como profilático (CONTRAINDICATIONS)\\n• Evitar terapêutica concomitante com outros fármacos que causem depressão da medula óssea (Drug Interactions)\\n• Precaução em neonatos e prematuros (Gray syndrome) — ajustar dose e monitorizar níveis (Pediatric Use)\\n• Usar apenas se o benefício justificar o risco na gravidez (atravessa a placenta; Cat C) e no aleitamento (excretado no leite)',
   E'• Contraindicated in patients with a history of hypersensitivity or previous toxic reaction; do not use in trivial infections, colds, influenza, throat infections or as a prophylactic agent (CONTRAINDICATIONS)\\n• Avoid concomitant therapy with other drugs that may cause bone marrow depression (Drug Interactions)\\n• Caution in neonates and premature infants (Gray syndrome) — adjust dose and monitor levels (Pediatric Use)\\n• Use only if benefit justifies risk in pregnancy (crosses the placenta; Cat C) and in breastfeeding (excreted in milk)',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Cloranfenicol (FRESENIUS KABI USA, LLC): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=aed29594-211d-49ef-813f-131975a8d0e3',
   'DailyMed/FDA (NIH/NLM) — approved Chloramphenicol label (FRESENIUS KABI USA, LLC): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=aed29594-211d-49ef-813f-131975a8d0e3'),

  ('dissulfiram',
   E'O dissulfiram é um medicamento de apoio no tratamento do alcoolismo crónico: se a pessoa beber álcool durante o tratamento, sente reações muito desconfortáveis (rubor, taquicardia, náuseas), o que ajuda a manter a abstinência. Só deve ser usado com motivação e apoio psicoterapêutico.',
   E'Disulfiram is a medicine that supports the treatment of chronic alcoholism: if the person drinks alcohol during treatment, they experience very uncomfortable reactions (flushing, tachycardia, nausea), which helps maintain abstinence. It should only be used with motivation and psychotherapeutic support.',
   E'Anti-alcoólico: inibe irreversivelmente a aldeído desidrogenase, aumentando a concentração de acetaldeído após a ingestão de álcool — reação dissulfiram-álcool (rubor, taquicardia, hipotensão, náuseas/vómitos) que desencoraja a ingestão. Diminui a taxa de metabolismo de certos fármacos, aumentando os seus níveis e o risco de toxicidade (rótulo FDA Drug Interactions).',
   E'Alcohol deterrent: irreversibly inhibits aldehyde dehydrogenase, increasing acetaldehyde concentration after alcohol intake — disulfiram-alcohol reaction (flushing, tachycardia, hypotension, nausea/vomiting) that discourages intake. It decreases the metabolism rate of certain drugs, increasing their levels and the risk of toxicity (FDA label Drug Interactions).',
   E'• Auxílio no tratamento de doentes alcoólicos crónicos selecionados que querem manter um estado de sobriedade forçada, para que o apoio psicoterapêutico possa ser aplicado (rótulo FDA INDICATIONS AND USAGE)',
   E'• Aid in the management of selected chronic alcohol patients who want to remain in a state of enforced sobriety so that supportive and psychotherapeutic treatment may be applied (FDA label INDICATIONS AND USAGE)',
   E'• Hepatite (colestática e fulminante), incluindo falência hepática com transplante ou morte — risco grave (WARNINGS)\\n• Neurite ótica, neurite periférica, polineurite, neuropatia periférica (WARNINGS)\\n• Erupções cutâneas (controláveis com anti-histamínico), sonolência transitória, fadiga, impotência, cefaleias, erupções acneiformes, gosto metálico',
   E'• Hepatitis (cholestatic and fulminant), including hepatic failure leading to transplantation or death — serious risk (WARNINGS)\\n• Optic neuritis, peripheral neuritis, polyneuritis, peripheral neuropathy (WARNINGS)\\n• Skin eruptions (controlled by antihistamines), transient drowsiness, fatigue, impotence, headache, acneiform eruptions, metallic taste',
   E'• Usar com precaução em doentes a tomar fenitoína (intoxicação por fenitoína — obter nível sérico basal e repetir após início); ajustar dose de anticoagulantes orais (prolonga o tempo de protrombina); vigiar doentes com isoniazida (marcha instável, alterações do estado mental) (Drug Interactions)\\n• Segurança na gravidez não estabelecida — usar apenas se o benefício provável superar os riscos (Usage in Pregnancy)\\n• Não administrar a mães a amamentar (Nursing Mothers)\\n• Vigiar sinais de hepatite (sintomas prodrómicos: fadiga, anorexia, diarreia, náuseas); monitorizar testes hepáticos',
   E'• Use with caution in patients taking phenytoin (phenytoin intoxication — obtain baseline serum level and repeat after initiation); adjust oral anticoagulant dose (prolongs prothrombin time); observe patients on isoniazid (unsteady gait, mental status changes) (Drug Interactions)\\n• Safety in pregnancy not established — use only if the probable benefit outweighs the risks (Usage in Pregnancy)\\n• Do not give to nursing mothers (Nursing Mothers)\\n• Watch for signs of hepatitis (prodromal symptoms: fatigue, anorexia, diarrhoea, nausea); monitor liver tests',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Dissulfiram (ALVOGEN INC.): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b90f8ff4-4fb3-46ab-8149-cb55f24a4044',
   'DailyMed/FDA (NIH/NLM) — approved Disulfiram label (ALVOGEN INC.): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b90f8ff4-4fb3-46ab-8149-cb55f24a4044'),

  ('ertapenem',
   E'O ertapenem é um antibiótico injetável da família dos carbapenemos, usado no tratamento de várias infeções graves (abdominais, pulmonares, urinárias, da pele, pélvicas) e na prevenção de infeções após cirurgia do cólon ou reto.',
   E'Ertapenem is an injectable carbapenem antibiotic, used to treat various serious infections (abdominal, lung, urinary, skin, pelvic) and to prevent infections after colon or rectal surgery.',
   E'Carbapenemo (antibiótico beta-lactâmico injetável, iv/im): bactericida por inibição da síntese da parede celular bacteriana; estável a muitas beta-lactamases, incluindo ESBL. Uso hospitalar em infeções polimicrobianas mistas (intra-abdominais, pneumonia, infeções urinárias complicadas, pé diabético, pélvicas) e profilaxia cirúrgica colorretal (rótulo FDA INDICATIONS AND USAGE).',
   E'Carbapenem (injectable beta-lactam antibiotic, IV/IM): bactericidal by inhibiting bacterial cell wall synthesis; stable to many beta-lactamases, including ESBLs. Hospital use in mixed polymicrobial infections (intra-abdominal, pneumonia, complicated UTI, diabetic foot, pelvic) and colorectal surgical prophylaxis (FDA label INDICATIONS AND USAGE).',
   E'• Infeções intra-abdominais complicadas, pielonefrite e infeções urinárias complicadas, pneumonia, infeções da pele e tecidos moles, infeções pélvicas agudas\\n• Profilaxia da infeção no local cirúrgico após cirurgia eletiva colorretal\\n• Espetro: S. aureus (MSSA), S. agalactiae, S. pneumoniae, S. pyogenes, E. coli, H. influenzae, K. pneumoniae, M. catarrhalis, P. mirabilis, anaeróbios (rótulo FDA INDICATIONS AND USAGE)',
   E'• Complicated intra-abdominal infections, pyelonephritis and complicated UTI, pneumonia, skin and soft tissue infections, acute pelvic infections\\n• Prophylaxis of surgical site infection after elective colorectal surgery\\n• Spectrum: S. aureus (MSSA), S. agalactiae, S. pneumoniae, S. pyogenes, E. coli, H. influenzae, K. pneumoniae, M. catarrhalis, P. mirabilis, anaerobes (FDA label INDICATIONS AND USAGE)',
   E'• Diarreia (incl. diarreia associada a Clostridium difficile), náuseas, cefaleias, reações no local de infusão\\n• Comichão, erupção cutânea\\n• Aumento das transaminases, trombocitose, eosinofilia\\n• Convulsões e atividade mioclónica (relacionadas com a dose — precaução em doentes com alterações do SNC ou insuficiência renal)',
   E'• Diarrhoea (incl. Clostridium difficile-associated diarrhoea), nausea, headache, infusion site reactions\\n• Pruritus, rash\\n• Elevated transaminases, thrombocytosis, eosinophilia\\n• Seizures and myoclonic activity (dose-related — caution in patients with CNS disorders or renal impairment)',
   E'• Contraindicado em doentes com hipersensibilidade a qualquer componente, a outros fármacos da mesma classe, ou com reações anafiláticas a beta-lactâmicos; IM contraindicado com hipersensibilidade à lidocaína (diluente) (CONTRAINDICATIONS)\\n• Não recomendada a co-administração com probenecida (aumenta as concentrações plasmáticas — 7.1)\\n• Reduz as concentrações de ácido valproico (risco de crises de breakthrough) — considerar terapêutica antiepilética alternativa (7.2)\\n• Precaução em doentes com história de convulsões e na insuficiência renal (ajustar dose)',
   E'• Contraindicated in patients with hypersensitivity to any component, to other drugs of the same class, or with anaphylactic reactions to beta-lactams; IM contraindicated with lidocaine hypersensitivity (diluent) (CONTRAINDICATIONS)\\n• Co-administration with probenecid is not recommended (increases plasma concentrations — 7.1)\\n• Reduces valproic acid concentrations (risk of breakthrough seizures) — consider alternative antiepileptic therapy (7.2)\\n• Caution in patients with a history of seizures and in renal impairment (dose adjustment)',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Ertapenem (INVANZ, MERCK SHARP & DOHME LLC): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=33f3b99b-fa82-42e0-26bf-f49891ae3d22',
   'DailyMed/FDA (NIH/NLM) — approved Ertapenem label (INVANZ, MERCK SHARP & DOHME LLC): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=33f3b99b-fa82-42e0-26bf-f49891ae3d22'),

  ('indacaterol',
   E'O indacaterol é um broncodilatador de longa duração (uma toma diária), usado no tratamento de manutenção da doença pulmonar obstrutiva crónica (DPOC) e da asma em adultos. Abre as vias aéreas e alivia a falta de ar, mas não é para crises agudas.',
   E'Indacaterol is a long-acting bronchodilator (once daily), used for maintenance treatment of chronic obstructive pulmonary disease (COPD) and asthma in adults. It opens the airways and relieves breathlessness, but is not for acute attacks.',
   E'Agonista beta-2 adrenérgico seletivo de longa duração (LABA, inalado, uma toma diária): ativa os recetores beta-2 no músculo liso brônquico, inibindo a contracção e promovendo a broncodilatação. Usado na manutenção da obstrução das vias aéreas na DPOC (e asma) — sem efeitos anti-inflamatórios clinicamente relevantes; não aconselhado na crise aguda (Prontuário 5.1.1). O QUADRO 2 (Anexo 7) documenta: inibidores do CYP3A4 e da P-gp aumentam até 2× os níveis plasmáticos; potenciação simpaticomimética com outros agonistas beta-2; potenciação do efeito hipocaliémico com metilxantinas, corticosteroides e diuréticos não poupadores de potássio.',
   E'Selective long-acting beta-2 adrenergic agonist (LABA, inhaled, once daily): activates beta-2 receptors on bronchial smooth muscle, inhibiting contraction and promoting bronchodilation. Used in maintenance of airway obstruction in COPD (and asthma) — no clinically relevant anti-inflammatory effects; not advised in acute attacks (Prontuário 5.1.1). QUADRO 2 (Annex 7) documents: CYP3A4 and P-gp inhibitors increase plasma levels up to 2-fold; sympathomimetic potentiation with other beta-2 agonists; potentiation of the hypokalaemic effect with methylxanthines, corticosteroids and non-potassium-sparing diuretics.',
   E'• Tratamento de manutenção da obstrução das vias aéreas em adultos com DPOC — uma toma diária (Prontuário 5.1.1)\\n• Indicado na terapêutica regular da asma ligeira a moderada (sintomas nocturnos) em associação com corticosteroide inalado (5.1)',
   E'• Maintenance treatment of airway obstruction in adults with COPD — once daily (Prontuário 5.1.1)\\n• Indicated for regular asthma therapy (mild to moderate, nocturnal symptoms) in combination with an inhaled corticosteroid (5.1)',
   E'• Tosse, irritação da garganta, nasofaringite\\n• Taquicardia, palpitações (efeito beta-adrenérgico)\\n• Hipocaliemia (sobretudo com diuréticos, metilxantinas, corticosteroides — QUADRO 2)\\n• Cefaleias, tremores, cãibras musculares\\n• Broncospasmo paradoxal (raro)',
   E'• Cough, throat irritation, nasopharyngitis\\n• Tachycardia, palpitations (beta-adrenergic effect)\\n• Hypokalaemia (especially with diuretics, methylxanthines, corticosteroids — QUADRO 2)\\n• Headache, tremor, muscle cramps\\n• Paradoxical bronchospasm (rare)',
   E'• Não usar em agudizações de asma/DPOC (broncodilatador de manutenção; nas crises usar agonista beta-2 de curta duração) (Prontuário 5.1.1)\\n• Os LABA não devem ser usados sem corticoide inalado na asma (risco acrescido de morte relacionada com asma)\\n• Precaução em doença cardiovascular (taquicardia, arritmias), hipertiroidismo, diabetes (hiperglicemia) e hipocaliemia\\n• Vigiar níveis de potássio quando associado a diuréticos, metilxantinas ou corticosteroides (QUADRO 2)',
   E'• Do not use in acute exacerbations of asthma/COPD (maintenance bronchodilator; in attacks use a short-acting beta-2 agonist) (Prontuário 5.1.1)\\n• LABAs should not be used without an inhaled corticosteroid in asthma (increased risk of asthma-related death)\\n• Caution in cardiovascular disease (tachycardia, arrhythmias), hyperthyroidism, diabetes (hyperglycaemia) and hypokalaemia\\n• Monitor potassium levels when combined with diuretics, methylxanthines or corticosteroids (QUADRO 2)',
   'Prontuário Terapêutico do INFARMED (11.ª ed., 2012) — Agonistas adrenérgicos beta (5.1.1) e QUADRO 2 do Anexo 7 (Indacaterol)',
   'Prontuário Terapêutico do INFARMED (11th ed., 2012) — Beta adrenergic agonists (5.1.1) and QUADRO 2 of Annex 7 (Indacaterol)'),

  ('ivabradina',
   E'A ivabradina é um medicamento que baixa a frequência cardíaca, usado na insuficiência cardíaca crónica em doentes com ritmo sinusal e frequência cardíaca elevada, e na angina de peito em doentes que não toleram beta-bloqueadores. Reduz o trabalho do coração.',
   E'Ivabradine is a medicine that lowers heart rate, used in chronic heart failure in patients with sinus rhythm and elevated heart rate, and in angina in patients who cannot tolerate beta-blockers. It reduces the work of the heart.',
   E'Inibidor seletivo do canal If do nó sinusal: reduz a frequência cardíaca de forma dependente da dose, sem efeitos na condução intracardíaca, contractilidade ou repolarização (efeito cronotrópico puro). Indicada na IC crónica sintomática (FEVE ≤ 35%, ritmo sinusal, FC ≥ 70 bpm) em doentes em doses máximas toleradas de beta-bloqueador ou com contraindicação/Intolerância ao beta-bloqueador (rótulo FDA INDICATIONS AND USAGE). Metabolizada pelo CYP3A4 — interações relevantes com inibidores/indutores (7.1).',
   E'Selective inhibitor of the If channel of the sinus node: reduces heart rate in a dose-dependent manner, without effects on intracardiac conduction, contractility or repolarisation (pure chronotropic effect). Indicated in chronic symptomatic HF (LVEF ≤ 35%, sinus rhythm, HR ≥ 70 bpm) in patients on maximally tolerated beta-blocker doses or with beta-blocker contraindication/intolerance (FDA label INDICATIONS AND USAGE). Metabolised by CYP3A4 — relevant interactions with inhibitors/inducers (7.1).',
   E'• Redução do risco de hospitalização por agravamento da insuficiência cardíaca em adultos com IC crónica estável e sintomática, FEVE ≤ 35%, ritmo sinusal e FC em repouso ≥ 70 bpm, em doses máximas toleradas de beta-bloqueador ou com contraindicação/intolerância (rótulo FDA 1.1)',
   E'• Reduction of the risk of hospitalisation for worsening heart failure in adults with stable, symptomatic chronic heart failure, LVEF ≤ 35%, sinus rhythm and resting HR ≥ 70 bpm, on maximally tolerated beta-blocker doses or with beta-blocker contraindication/intolerance (FDA label 1.1)',
   E'• Bradicardia sintomática, bloqueios de condução\\n• Fibrilhação auricular (monitorizar o ritmo — 5.2)\\n• Fenómenos luminosos (fosfenos) — transitórios e reversíveis (5.6)\\n• Cefaleias, tonturas, visão turva\\n• Toxicidade fetal (dados animais — 5.1)',
   E'• Symptomatic bradycardia, conduction blocks\\n• Atrial fibrillation (monitor rhythm — 5.2)\\n• Luminous phenomena (phosphenes) — transient and reversible (5.6)\\n• Headache, dizziness, blurred vision\\n• Fetal toxicity (animal data — 5.1)',
   E'• Contraindicada em: IC descompensada aguda, hipotensão clinicamente significativa, síndrome do nó sinusal, bloqueio sinoauricular ou bloqueio AV de 3.º grau sem pacemaker, bradicardia clinicamente significativa e insuficiência hepática grave (CONTRAINDICATIONS)\\n• Pode causar toxicidade fetal (dados animais) — recomendar contraceção eficaz em mulheres em idade fértil (5.1)\\n• Contraindicado o uso concomitante com inibidores fortes do CYP3A4 (azóis, macrólidos como claritromicina/telitromicina, inibidores da protease) e evitar inibidores moderados (diltiazem, verapamilo, sumo de toranja) (7.1)\\n• Monitorizar o ritmo (risco de FA) e a frequência cardíaca (bradicardia < 50 bpm → reduzir dose)',
   E'• Contraindicated in: acute decompensated HF, clinically significant hypotension, sick sinus syndrome, sinoatrial block or third-degree AV block without a pacemaker, clinically significant bradycardia and severe hepatic impairment (CONTRAINDICATIONS)\\n• May cause fetal toxicity (animal data) — advise effective contraception in women of reproductive potential (5.1)\\n• Concomitant use with strong CYP3A4 inhibitors is contraindicated (azoles, macrolides such as clarithromycin/telithromycin, HIV protease inhibitors) and moderate inhibitors should be avoided (diltiazem, verapamil, grapefruit juice) (7.1)\\n• Monitor rhythm (AF risk) and heart rate (bradycardia < 50 bpm → reduce dose)',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Ivabradina (CORLANOR, AMGEN INC.): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=92018a65-38f6-45f7-91d4-a34921b81d0d',
   'DailyMed/FDA (NIH/NLM) — approved Ivabradine label (CORLANOR, AMGEN INC.): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=92018a65-38f6-45f7-91d4-a34921b81d0d'),

  ('levodopa',
   E'A levodopa é o tratamento mais eficaz para a doença de Parkinson: é convertida no cérebro em dopamina, a substância que falta nesta doença, e alivia os sintomas motores (tremor, rigidez, lentidão). Costuma ser usada em associação com carbidopa para reduzir efeitos secundários e melhorar a eficácia.',
   E'Levodopa is the most effective treatment for Parkinson\'s disease: it is converted in the brain into dopamine, the substance that is lacking in this disease, and relieves motor symptoms (tremor, rigidity, slowness). It is usually used in combination with carbidopa to reduce side effects and improve efficacy.',
   E'Precursor da dopamina: atravessa a barreira hematoencefálica e é descarboxilado em dopamina no cérebro (pela DOPA descarboxilase), repondo o défice dopaminérgico do corpo estriado. A carbidopa (inibidor periférico da descarboxilase) reduz a dose necessária em ~75% e os efeitos periféricos. Rótulo SINEMET (carbidopa + levodopa, ORGANON) usado como referência (a levodopa pura não é comercializada isoladamente nos EUA).',
   E'Dopamine precursor: crosses the blood-brain barrier and is decarboxylated to dopamine in the brain (by DOPA decarboxylase), replenishing the striatal dopaminergic deficit. Carbidopa (peripheral decarboxylase inhibitor) reduces the required dose by ~75% and peripheral effects. SINEMET label (carbidopa + levodopa, ORGANON) used as reference (plain levodopa is not marketed alone in the US).',
   E'• Tratamento da doença de Parkinson, do parkinsonismo pós-encefalítico e do parkinsonismo sintomático após intoxicação por monóxido de carbono ou manganês (rótulo SINEMET INDICATIONS AND USAGE)',
   E'• Treatment of Parkinson\'s disease, post-encephalitic parkinsonism, and symptomatic parkinsonism following carbon monoxide or manganese intoxication (SINEMET label INDICATIONS AND USAGE)',
   E'• Náuseas, vómitos (início — reduzir com carbidopa)\\n• Discinesias (movimentos involuntários), distonia — relacionadas com a dose e a duração\\n• Hipotensão ortostática, tonturas\\n• Alucinações, confusão, sonolência (episódios de sono súbito)\\n• Hipertensão e discinesia com antidepressivos tricíclicos (Drug Interactions)',
   E'• Nausea, vomiting (early — reduced by carbidopa)\\n• Dyskinesias (involuntary movements), dystonia — dose- and duration-related\\n• Orthostatic hypotension, dizziness\\n• Hallucinations, confusion, somnolence (sudden sleep episodes)\\n• Hypertension and dyskinesia with tricyclic antidepressants (Drug Interactions)',
   E'• Contraindicado com inibidores da MAO não seletivos (ver CONTRAINDICATIONS) e em glaucoma de ângulo fechado e suspeita de melanoma (SINEMET CONTRAINDICATIONS)\\n• Os antagonistas dos recetores D2 (fenotiazinas, butirofenonas, risperidona) e a isoniazida reduzem o efeito terapêutico; a fenitoína e a papaverina revertem o benefício (Drug Interactions)\\n• Evitar com agentes depletores de dopamina (reserpina, tetrabenazina) (Drug Interactions)\\n• Sais de ferro formam quelatos e reduzem a biodisponibilidade — separar as tomas (Drug Interactions)\\n• Não suspender abruptamente (síndrome neuroléptico maligno-like)',
   E'• Contraindicated with non-selective MAO inhibitors (see CONTRAINDICATIONS) and in narrow-angle glaucoma and suspected melanoma (SINEMET CONTRAINDICATIONS)\\n• D2 receptor antagonists (phenothiazines, butyrophenones, risperidone) and isoniazid reduce the therapeutic effect; phenytoin and papaverine reverse the benefit (Drug Interactions)\\n• Avoid with dopamine-depleting agents (reserpine, tetrabenazine) (Drug Interactions)\\n• Iron salts form chelates and reduce bioavailability — separate dosing (Drug Interactions)\\n• Do not discontinue abruptly (neuroleptic malignant-like syndrome)',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Sinemet (carbidopa + levodopa, ORGANON LLC): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9b17b028-964a-473c-823d-81423535bd66',
   'DailyMed/FDA (NIH/NLM) — approved Sinemet label (carbidopa + levodopa, ORGANON LLC): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9b17b028-964a-473c-823d-81423535bd66'),

  ('ticagrelor',
   E'O ticagrelor é um medicamento antiagregante plaquetário que impede a formação de coágulos, usado depois de um enfarte ou síndrome coronária aguda e na prevenção de AVC e enfarte. Reduz a adesividade das plaquetas, diminuindo o risco de novos eventos.',
   E'Ticagrelor is an antiplatelet medicine that prevents clot formation, used after a heart attack or acute coronary syndrome and to prevent stroke and heart attack. It reduces platelet stickiness, lowering the risk of further events.',
   E'Antiagregante plaquetário: inibe reversivelmente o recetor P2Y12 do ADP nas plaquetas, impedindo a ativação e agregação plaquetária (mecanismo direto e reversível, sem necessidade de ativação metabólica; o metabolito ativo é equipotente). Reduz a morte CV, IAM e AVC em doentes com SCA ou história de IAM (rótulo FDA INDICATIONS AND USAGE). Substrato e inibidor moderado do CYP3A4.',
   E'Antiplatelet agent: reversibly inhibits the platelet P2Y12 ADP receptor, preventing platelet activation and aggregation (direct and reversible mechanism, no metabolic activation required; the active metabolite is equipotent). Reduces CV death, MI and stroke in patients with ACS or a history of MI (FDA label INDICATIONS AND USAGE). CYP3A4 substrate and moderate inhibitor.',
   E'• Redução do risco de morte cardiovascular, enfarte do miocárdio e AVC em doentes com síndrome coronária aguda ou história de enfarte do miocárdio (pelo menos os primeiros 12 meses após SCA)\\n• Redução do risco de trombose de stent (rótulo FDA 1.1)',
   E'• Reduction of the risk of cardiovascular death, myocardial infarction and stroke in patients with acute coronary syndrome or a history of MI (at least the first 12 months after ACS)\\n• Reduction of the risk of stent thrombosis (FDA label 1.1)',
   E'• Hemorragia (o risco aumenta com fármacos que inibem a função plaquetária — 5.1)\\n• Dispneia (transitória, dose-dependente)\\n• Hemorragias menores (equimoses, epistaxe, hemorragia gengival)\\n• Bradicardia, bloqueios AV\\n• Aumento da creatinina e do ácido úrico séricos',
   E'• Bleeding (the risk increases with drugs that inhibit platelet function — 5.1)\\n• Dyspnoea (transient, dose-dependent)\\n• Minor bleeding (bruising, epistaxis, gingival bleeding)\\n• Bradycardia, AV block\\n• Increased serum creatinine and uric acid',
   E'• Contraindicado em doentes com história de hemorragia intracraniana e em hemorragia ativa patológica (4.1/4.2)\\n• Evitar inibidores fortes do CYP3A (cetoconazol, itraconazol, voriconazol, claritromicina, ritonavir, atazanavir, entre outros) — aumentam a exposição e o risco de dispneia/hemorragia (7.1)\\n• Evitar indutores fortes do CYP3A (rifampicina, fenitoína, carbamazepina, fenobarbital) — reduzem a eficácia (7.2)\\n• Evitar a suspensão precoce em doentes com DAC (risco de IAM, AVC e morte — 5.2)\\n• Manter a aspirina ≤ 100 mg/dia (doses > 100 mg reduzem a eficácia); usar com precaução com outras terapêuticas que aumentem o risco hemorrágico',
   E'• Contraindicated in patients with a history of intracranial haemorrhage and in active pathological bleeding (4.1/4.2)\\n• Avoid strong CYP3A inhibitors (ketoconazole, itraconazole, voriconazole, clarithromycin, ritonavir, atazanavir, among others) — they increase exposure and the risk of dyspnoea/bleeding (7.1)\\n• Avoid strong CYP3A inducers (rifampin, phenytoin, carbamazepine, phenobarbital) — they reduce efficacy (7.2)\\n• Avoid premature discontinuation in CAD patients (risk of MI, stroke and death — 5.2)\\n• Keep aspirin ≤ 100 mg/day (doses > 100 mg reduce efficacy); use with caution with other therapies that increase bleeding risk',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Ticagrelor (BRILINTA, ASTRAZENECA PHARMACEUTICALS LP): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f7b3f443-e83d-4bf2-0e96-023448fed9a8',
   'DailyMed/FDA (NIH/NLM) — approved Ticagrelor label (BRILINTA, ASTRAZENECA PHARMACEUTICALS LP): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f7b3f443-e83d-4bf2-0e96-023448fed9a8'),

  ('diltiazem',
   E'O diltiazem é um medicamento da família dos bloqueadores dos canais de cálcio, usado para baixar a tensão arterial e tratar a angina de peito. Alivia o trabalho do coração e dilata os vasos sanguíneos.',
   E'Diltiazem is a calcium channel blocker, used to lower blood pressure and to treat angina pectoris. It reduces the work of the heart and dilates blood vessels.',
   E'Bloqueador dos canais de cálcio (benzotiazepina): inibe o influxo de cálcio nas células do músculo cardíaco e liso vascular, reduzindo a contractilidade, a condução AV e a resistência vascular periférica — anti-hipertensor e antianginoso. Substrato e inibidor da P-gp e do CYP3A4 — várias interações farmacocinéticas (rótulo TIAZAC Drug Interactions).',
   E'Calcium channel blocker (benzothiazepine): inhibits calcium influx into cardiac and vascular smooth muscle cells, reducing contractility, AV conduction and peripheral vascular resistance — antihypertensive and antianginal. Substrate and inhibitor of P-gp and CYP3A4 — several pharmacokinetic interactions (TIAZAC label Drug Interactions).',
   E'• Tratamento da hipertensão arterial (isolado ou em associação) (rótulo TIAZAC INDICATIONS AND USAGE)\\n• Tratamento da angina estável crónica',
   E'• Treatment of hypertension (alone or in combination) (TIAZAC label INDICATIONS AND USAGE)\\n• Treatment of chronic stable angina',
   E'• Edema periférico, cefaleias, tonturas\\n• Bradicardia, bloqueio AV (1.º grau), hipotensão\\n• Obstipação, náuseas, dispepsia\\n• Erupções cutâneas, rubor\\n• Elevação das transaminases (rara)',
   E'• Peripheral oedema, headache, dizziness\\n• Bradycardia, first-degree AV block, hypotension\\n• Constipation, nausea, dyspepsia\\n• Skin rash, flushing\\n• Elevated transaminases (rare)',
   E'• Contraindicado em: síndrome do nó sinusal sem pacemaker ventricular funcional, bloqueio AV de 2.º/3.º grau sem pacemaker, hipotensão grave (< 90 mmHg sistólica) e hipersensibilidade (CONTRAINDICATIONS)\\n• Efeitos aditivos na condução AV com beta-bloqueadores e digitálicos — titular com precaução (Drug Interactions)\\n• Aumenta a AUC de midazolam/triazolam (3-4×) — sedação prolongada (Drug Interactions)\\n• Interage com ciclosporina, carbamazepina, sinvastatina/lovastatina (inibidor CYP3A4/P-gp) — ajustar doses e vigiar toxicidade\\n• Precaução na insuficiência renal e hepática (exposição aumentada)',
   E'• Contraindicated in: sick sinus syndrome without a functioning ventricular pacemaker, second- or third-degree AV block without a pacemaker, severe hypotension (< 90 mm Hg systolic) and hypersensitivity (CONTRAINDICATIONS)\\n• Additive effects on AV conduction with beta-blockers and digitalis — titrate with caution (Drug Interactions)\\n• Increases midazolam/triazolam AUC (3-4×) — prolonged sedation (Drug Interactions)\\n• Interacts with cyclosporine, carbamazepine, simvastatin/lovastatin (CYP3A4/P-gp inhibitor) — adjust doses and monitor for toxicity\\n• Caution in renal and hepatic impairment (increased exposure)',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Diltiazem (TIAZAC ER, BAUSCH HEALTH US, LLC): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c567fe7e-887e-4291-a0d1-2dd3f25cbf25',
   'DailyMed/FDA (NIH/NLM) — approved Diltiazem label (TIAZAC ER, BAUSCH HEALTH US, LLC): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c567fe7e-887e-4291-a0d1-2dd3f25cbf25'),

  ('verapamilo',
   E'O verapamilo é um bloqueador dos canais de cálcio usado para baixar a tensão arterial, tratar a angina e controlar certas arritmias cardíacas. Reduz a frequência cardíaca e alivia o trabalho do coração.',
   E'Verapamil is a calcium channel blocker used to lower blood pressure, treat angina and control certain cardiac arrhythmias. It slows the heart rate and reduces the work of the heart.',
   E'Bloqueador dos canais de cálcio (fenilalquilamina): inibe o influxo de cálcio no miocárdio e no músculo liso vascular, com efeitos cronotrópico e dromotrópico negativos (retarda a condução AV) e vasodilatação arterial — anti-hipertensor, antianginoso e antiarrítmico (classe IV). Substrato do CYP3A4; inibidor da P-gp (rótulo VERAPAMIL ER).',
   E'Calcium channel blocker (phenylalkylamine): inhibits calcium influx in the myocardium and vascular smooth muscle, with negative chronotropic and dromotropic effects (slows AV conduction) and arterial vasodilation — antihypertensive, antianginal and antiarrhythmic (class IV). CYP3A4 substrate; P-gp inhibitor (VERAPAMIL ER label).',
   E'• Tratamento da hipertensão arterial (formas de libertação prolongada) (rótulo FDA INDICATIONS AND USAGE)\\n• Angina (variante, instável, esforço) e controlo da frequência ventricular em fibrilhação/flutter auricular (uso clínico)',
   E'• Treatment of hypertension (extended-release forms) (FDA label INDICATIONS AND USAGE)\\n• Angina (variant, unstable, effort) and ventricular rate control in atrial fibrillation/flutter (clinical use)',
   E'• Obstipação (comum), náuseas\\n• Hipotensão, tonturas, cefaleias\\n• Bradicardia, bloqueio AV, bradiarritmias\\n• Edema periférico\\n• Rubor, erupções cutâneas',
   E'• Constipation (common), nausea\\n• Hypotension, dizziness, headache\\n• Bradycardia, AV block, bradyarrhythmias\\n• Peripheral oedema\\n• Flushing, skin rash',
   E'• Contraindicado em: choque cardiogénico, bloqueio AV grave, síndrome do nó sinusal, hipotensão grave, insuficiência cardíaca grave e fibrilhação/flutter auricular com vias acessórias (WPW) (rótulo CONTRAINDICATIONS)\\n• Aumenta os níveis de carbamazepina, ciclosporina, digoxina e teofilina — monitorizar e ajustar (Drug Interactions)\\n• A rifampicina reduz marcadamente a biodisponibilidade oral; o fenobarbital aumenta o clearance (Drug Interactions)\\n• Monitorizar a neurotoxicidade do lítio na associação (níveis podem subir, descer ou manter-se) (Drug Interactions)\\n• Hipotensão e bradiarritmias com telitromicina (Drug Interactions)',
   E'• Contraindicated in: cardiogenic shock, severe AV block, sick sinus syndrome, severe hypotension, severe heart failure and atrial fibrillation/flutter with accessory pathways (WPW) (label CONTRAINDICATIONS)\\n• Increases levels of carbamazepine, cyclosporine, digoxin and theophylline — monitor and adjust (Drug Interactions)\\n• Rifampin markedly reduces oral bioavailability; phenobarbital increases clearance (Drug Interactions)\\n• Monitor lithium neurotoxicity in the combination (levels may rise, fall or stay unchanged) (Drug Interactions)\\n• Hypotension and bradyarrhythmias with telithromycin (Drug Interactions)',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Verapamilo (NIVAGEN PHARMACEUTICALS, INC.): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e36e485f-fbed-4e30-9a63-984931f2e54e',
   'DailyMed/FDA (NIH/NLM) — approved Verapamil label (NIVAGEN PHARMACEUTICALS, INC.): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e36e485f-fbed-4e30-9a63-984931f2e54e'),

  ('tacrolimus',
   E'O tacrolimus é um medicamento imunossupressor usado para evitar a rejeição após transplante de órgãos (rim, fígado, coração, pulmão). Reduz a atividade do sistema imunitário para que o corpo não ataque o órgão transplantado.',
   E'Tacrolimus is an immunosuppressant medicine used to prevent rejection after organ transplantation (kidney, liver, heart, lung). It reduces the activity of the immune system so the body does not attack the transplanted organ.',
   E'Imunossupressor (inibidor da calcineurina): liga-se à FKBP-12; o complexo tacrolimus-FKBP-12 inibe a calcineurina, impedindo a desfosforilação e translocação de fatores de transcrição (NFAT) e bloqueando a ativação dos linfócitos T. Substrato do CYP3A4/3A5 e da P-gp — janela terapêutica estreita, com muitas interações (rótulo PROGRAF).',
   E'Immunosuppressant (calcineurin inhibitor): binds to FKBP-12; the tacrolimus-FKBP-12 complex inhibits calcineurin, preventing the dephosphorylation and translocation of transcription factors (NFAT) and blocking T-lymphocyte activation. CYP3A4/3A5 and P-gp substrate — narrow therapeutic window, with many interactions (PROGRAF label).',
   E'• Profilaxia da rejeição de órgãos em doentes adultos e pediátricos submetidos a transplante alogénico de rim, fígado, coração ou pulmão (rótulo FDA 1.1)',
   E'• Prophylaxis of organ rejection in adult and paediatric patients receiving allogeneic kidney, liver, heart or lung transplant (FDA label 1.1)',
   E'• Nefrotoxicidade (aumento da creatinina — comum)\\n• Hiperglicemia/diabetes de novo pós-transplante, hipercaliemia\\n• Hipertensão, tremor, cefaleias, insónia\\n• Infeções e linfomas/malignidades (imunossupressão — 5.1)\\n• Diarreia, náuseas, dispepsia',
   E'• Nephrotoxicity (increased creatinine — common)\\n• Hyperglycaemia/new-onset post-transplant diabetes, hyperkalaemia\\n• Hypertension, tremor, headache, insomnia\\n• Infections and lymphomas/malignancies (immunosuppression — 5.1)\\n• Diarrhoea, nausea, dyspepsia',
   E'• Contraindicado em doentes com hipersensibilidade ao tacrolimus (e, na forma IV, ao HCO-60) (CONTRAINDICATIONS)\\n• Com ácido micofenólico: a exposição ao MPA é maior com tacrolimus do que com ciclosporina — monitorizar reações adversas do MPA (7.1)\\n• Inibidores do CYP3A4/P-gp (azóis, macrólidos, verapamilo, diltiazem) aumentam os níveis de tacrolimus; indutores (rifampicina, fenobarbital, fenitoína, carbamazepina) diminuem — ajustar dose e monitorizar níveis (7.2)\\n• Monitorizar níveis sanguíneos (janela estreita), função renal, glicemia, potássio e tensão arterial',
   E'• Contraindicated in patients with hypersensitivity to tacrolimus (and, IV form, to HCO-60) (CONTRAINDICATIONS)\\n• With mycophenolic acid: MPA exposure is higher with tacrolimus than with cyclosporine — monitor for MPA-associated adverse reactions (7.1)\\n• CYP3A4/P-gp inhibitors (azoles, macrolides, verapamil, diltiazem) increase tacrolimus levels; inducers (rifampin, phenobarbital, phenytoin, carbamazepine) decrease them — adjust dose and monitor levels (7.2)\\n• Monitor blood levels (narrow window), renal function, glycaemia, potassium and blood pressure',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Tacrolimus (PROGRAF, ASTELLAS PHARMA US, INC.): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7f667de1-9dfa-4bd6-8ba0-15ee2d78873b',
   'DailyMed/FDA (NIH/NLM) — approved Tacrolimus label (PROGRAF, ASTELLAS PHARMA US, INC.): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7f667de1-9dfa-4bd6-8ba0-15ee2d78873b'),

  ('sirolimus',
   E'O sirolimus é um medicamento imunossupressor usado para evitar a rejeição após transplante renal. Reduz a atividade do sistema imunitário para que o corpo não ataque o rim transplantado.',
   E'Sirolimus is an immunosuppressant medicine used to prevent rejection after kidney transplantation. It reduces the activity of the immune system so the body does not attack the transplanted kidney.',
   E'Imunossupressor (inibidor do mTOR): liga-se à FKBP-12; o complexo sirolimus-FKBP-12 inibe a mTOR, bloqueando a ativação e proliferação dos linfócitos T em resposta a estímulos antigénicos e citocínicos (IL-2, IL-4, IL-15) e a produção de anticorpos — mecanismo distinto de outros imunossupressores. Substrato do CYP3A4 e da P-gp (rótulo FDA 12.1/7).',
   E'Immunosuppressant (mTOR inhibitor): binds to FKBP-12; the sirolimus-FKBP-12 complex inhibits mTOR, blocking T-lymphocyte activation and proliferation in response to antigenic and cytokine stimuli (IL-2, IL-4, IL-15) and antibody production — a mechanism distinct from other immunosuppressants. CYP3A4 and P-gp substrate (FDA label 12.1/7).',
   E'• Profilaxia da rejeição de órgãos em doentes com 13 ou mais anos submetidos a transplante renal (rótulo FDA 1.1)',
   E'• Prophylaxis of organ rejection in patients aged 13 years or older receiving renal transplants (FDA label 1.1)',
   E'• Hiperlipidemia (colesterol e triglicéridos elevados), hipertrigliceridemia\\n• Estomatite/úlceras orais, diarreia, náuseas, dor abdominal\\n• Trombocitopenia, leucopenia, anemia\\n• Edema periférico, acne, artralgias\\n• Infeções e linfomas/malignidades (imunossupressão — 5.1)',
   E'• Hyperlipidaemia (elevated cholesterol and triglycerides), hypertriglyceridaemia\\n• Stomatitis/oral ulcers, diarrhoea, nausea, abdominal pain\\n• Thrombocytopenia, leukopenia, anaemia\\n• Peripheral oedema, acne, arthralgia\\n• Infections and lymphomas/malignancies (immunosuppression — 5.1)',
   E'• Contraindicado em doentes com hipersensibilidade ao sirolimus (CONTRAINDICATIONS)\\n• A ciclosporina aumenta as concentrações de sirolimus — administrar sirolimus 4 horas após a ciclosporina (7.1)\\n• Indutores do CYP3A4/P-gp (rifampicina, fenobarbital, fenitoína, carbamazepina) diminuem as concentrações; inibidores (azóis, macrólidos, verapamilo, diltiazem) aumentam — monitorizar níveis (7)\\n• Monitorizar lípidos, função renal, contagem sanguínea e sinais de infeção\\n• Pode causar dano fetal (dados animais e mecanismo de ação)',
   E'• Contraindicated in patients with hypersensitivity to sirolimus (CONTRAINDICATIONS)\\n• Cyclosporine increases sirolimus concentrations — administer sirolimus 4 hours after cyclosporine (7.1)\\n• CYP3A4/P-gp inducers (rifampin, phenobarbital, phenytoin, carbamazepine) decrease concentrations; inhibitors (azoles, macrolides, verapamil, diltiazem) increase them — monitor levels (7)\\n• Monitor lipids, renal function, blood counts and signs of infection\\n• May cause fetal harm (animal data and mechanism of action)',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Sirolimus (MYLAN PHARMACEUTICALS INC.): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5908cd1a-fc5a-462f-99ed-1d8983e253c9',
   'DailyMed/FDA (NIH/NLM) — approved Sirolimus label (MYLAN PHARMACEUTICALS INC.): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5908cd1a-fc5a-462f-99ed-1d8983e253c9'),

  ('micofenolato',
   E'O micofenolato é um medicamento imunossupressor usado para evitar a rejeição após transplante de rim, coração ou fígado, em associação com outros imunossupressores. Reduz a atividade do sistema imunitário.',
   E'Mycophenolate is an immunosuppressant medicine used to prevent rejection after kidney, heart or liver transplantation, in combination with other immunosuppressants. It reduces the activity of the immune system.',
   E'Imunossupressor: o micofenolato de mofetilo (MMF) é absorvido e hidrolisado em ácido micofenólico (MPA), o metabolito ativo — inibidor seletivo não competitivo da IMPDH (inosina monofosfato desidrogenase), bloqueando a síntese de novo de guanosina e a proliferação de linfócitos (rótulo CELLCEPT 12.1). Embriotoxina conhecida — REMS com contraceção obrigatória.',
   E'Immunosuppressant: mycophenolate mofetil (MMF) is absorbed and hydrolysed to mycophenolic acid (MPA), the active metabolite — a selective uncompetitive inhibitor of IMPDH (inosine monophosphate dehydrogenase), blocking de novo guanosine synthesis and lymphocyte proliferation (CELLCEPT label 12.1). Known embryotoxin — REMS with mandatory contraception.',
   E'• Profilaxia da rejeição de órgãos em recetores adultos e pediátricos (≥ 3 meses) de transplante alogénico de rim, coração ou fígado, em associação com outros imunossupressores (rótulo FDA 1.1)',
   E'• Prophylaxis of organ rejection in adult and paediatric recipients (≥ 3 months) of allogeneic kidney, heart or liver transplants, in combination with other immunosuppressants (FDA label 1.1)',
   E'• Diarreia, vómitos, dor abdominal, dispepsia (comuns)\\n• Leucopenia, anemia, trombocitopenia (mielossupressão)\\n• Infeções (incl. oportunistas) e linfomas/malignidades (imunossupressão — 5.2)\\n• Embriotoxicidade: perda da gravidez no 1.º trimestre e malformações congénitas múltiplas (5.1)\\n• Hipertensão, edema, hipercaliemia',
   E'• Diarrhoea, vomiting, abdominal pain, dyspepsia (common)\\n• Leukopenia, anaemia, thrombocytopenia (myelosuppression)\\n• Infections (incl. opportunistic) and lymphomas/malignancies (immunosuppression — 5.2)\\n• Embryotoxicity: first-trimester pregnancy loss and multiple congenital malformations (5.1)\\n• Hypertension, oedema, hyperkalaemia',
   E'• Contraindicado em doentes com história de hipersensibilidade (incl. anafilaxia) ao MMF, ao MPA ou a qualquer componente (CONTRAINDICATIONS)\\n• Embriotoxicidade: risco aumentado de perda no 1.º trimestre e malformações (ouvido externo, face, lábio/palato, membros, coração, esófago, rim e sistema nervoso) — evitar na gravidez se houver alternativas mais seguras; teste de gravidez e contraceção obrigatórios (5.1)\\n• Antiácidos com magnésio/alumínio e IBP reduzem a exposição ao MPA — separar as tomas (antiácidos: ≥ 2 h após; 7.1)\\n• Fármacos que interferem com a circulação entero-hepática (colestiramina, antibióticos) reduzem a exposição (7.1)\\n• Monitorizar hemograma (leucopenia), função renal e sinais de infeção',
   E'• Contraindicated in patients with a history of hypersensitivity (including anaphylaxis) to MMF, MPA or any component (CONTRAINDICATIONS)\\n• Embryotoxicity: increased risk of first-trimester loss and malformations (external ear, face, cleft lip/palate, limbs, heart, oesophagus, kidney and nervous system) — avoid in pregnancy if safer options exist; pregnancy testing and contraception are mandatory (5.1)\\n• Antacids with magnesium/aluminium and PPIs reduce MPA exposure — separate dosing (antacids: at least 2 h after; 7.1)\\n• Drugs that interfere with enterohepatic recirculation (cholestyramine, antibiotics) reduce exposure (7.1)\\n• Monitor blood counts (leukopenia), renal function and signs of infection',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Micofenolato (CELLCEPT, GENENTECH, INC.): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=37241e87-4af4-4dc3-a1aa-ea6f20d8dc40',
   'DailyMed/FDA (NIH/NLM) — approved Mycophenolate label (CELLCEPT, GENENTECH, INC.): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=37241e87-4af4-4dc3-a1aa-ea6f20d8dc40'),

  ('pimozida',
   E'A pimozida é um medicamento antipsicótico usado no tratamento dos tiques da síndrome de Tourette, em doentes que não respondem a outras terapêuticas. Deve ser usado com precaução, com monitorização do eletrocardiograma, porque pode afetar o ritmo do coração.',
   E'Pimozide is an antipsychotic medicine used to treat tics in Tourette syndrome, in patients who do not respond to other therapies. It should be used with caution, with ECG monitoring, because it can affect the heart rhythm.',
   E'Antipsicótico (neuroléptico difenilbutilpiperidina): antagonista dopaminérgico D2 (bloqueio dos recetores D2) — reduz os tiques na síndrome de Tourette. Prolonga o intervalo QT do eletrocardiograma — efeito aditivo com outros fármacos que prolongam o QT; metabolizado principalmente pelo CYP3A4 (também CYP1A2 e CYP2D6) (rótulo FDA).',
   E'Antipsychotic (diphenylbutylpiperidine neuroleptic): dopaminergic D2 antagonist (D2 receptor blockade) — reduces tics in Tourette syndrome. Prolongs the ECG QT interval — additive effect with other QT-prolonging drugs; metabolised mainly by CYP3A4 (also CYP1A2 and CYP2D6) (FDA label).',
   E'• Tratamento dos tiques da síndrome de Gilles de la Tourette em doentes com tiques graves incapacitantes ou que não respondem a terapêutica padrão (uso clínico; rótulo FDA)',
   E'• Treatment of tics in Gilles de la Tourette syndrome in patients with severe, disabling tics or who do not respond to standard therapy (clinical use; FDA label)',
   E'• Prolongamento do QT e arritmias ventriculares (incl. torsades de pointes) — monitorizar ECG (Drug Interactions)\\n• Sonolência, sedação, tonturas\\n• Sintomas extrapiramidais (distonia, acatisia, parkinsonismo), discinesia tardia\\n• Boca seca, obstipação, visão turva\\n• Ganho de peso, hiperprolactinemia',
   E'• QT prolongation and ventricular arrhythmias (incl. torsades de pointes) — monitor ECG (Drug Interactions)\\n• Somnolence, sedation, dizziness\\n• Extrapyramidal symptoms (dystonia, akathisia, parkinsonism), tardive dyskinesia\\n• Dry mouth, constipation, blurred vision\\n• Weight gain, hyperprolactinaemia',
   E'• Não administrar com fármacos que prolongam o QT (dofetilida, sotalol, quinidina, outros antiarrítmicos classe Ia/III, mesoridazina, tioridazina, clorpromazina, droperidol, macrólidos, moxifloxacina, halofantrina, mefloquina, pentamidina, tacrolimus, ziprasidona, entre outros) — risco de arritmias (Drug Interactions)\\n• Precaução com os inibidores do CYP3A4, CYP1A2 e CYP2D6 (aumentam os níveis de pimozida) (Drug Interactions)\\n• Metabolizadores fracos do CYP2D6 (5-10% da população) têm concentrações mais altas (Pharmacogenomics)\\n• Monitorizar ECG (intervalo QT), potássio e magnésio séricos antes e durante o tratamento; evitar em hipocaliemia/hipomagnesemia',
   E'• Do not administer with QT-prolonging drugs (dofetilide, sotalol, quinidine, other class Ia/III antiarrhythmics, mesoridazine, thioridazine, chlorpromazine, droperidol, macrolides, moxifloxacin, halofantrine, mefloquine, pentamidine, tacrolimus, ziprasidone, among others) — risk of arrhythmias (Drug Interactions)\\n• Caution with CYP3A4, CYP1A2 and CYP2D6 inhibitors (they increase pimozide levels) (Drug Interactions)\\n• Poor CYP2D6 metabolisers (5-10% of the population) have higher concentrations (Pharmacogenomics)\\n• Monitor ECG (QT interval), serum potassium and magnesium before and during treatment; avoid in hypokalaemia/hypomagnesaemia',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Pimozida (ANI PHARMACEUTICALS, INC.): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4e954fc2-fdff-486c-beb6-2b8ace717081',
   'DailyMed/FDA (NIH/NLM) — approved Pimozide label (ANI PHARMACEUTICALS, INC.): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4e954fc2-fdff-486c-beb6-2b8ace717081')
) AS v(slug, overview_public_pt, overview_public_en, overview_pro_pt, overview_pro_en,
        indications_pt, indications_en, side_effects_pt, side_effects_en,
        precautions_pt, precautions_en, source_pt, source_en)
ON d.slug = v.slug
ON CONFLICT (drug_id) DO NOTHING;
-- =====================================================================
-- 3. Farmacologia (drug_pharmacology) — padrão 7.6
-- =====================================================================
INSERT INTO public.drug_pharmacology
  (drug_id, pharmacodynamics_pt, pharmacodynamics_en, mechanism_pt, mechanism_en,
   metabolism_pt, metabolism_en, absorption_pt, absorption_en,
   half_life_pt, half_life_en, source_pt, source_en, status)
SELECT d.id, v.pharmacodynamics_pt, v.pharmacodynamics_en, v.mechanism_pt, v.mechanism_en,
       v.metabolism_pt, v.metabolism_en, v.absorption_pt, v.absorption_en,
       v.half_life_pt, v.half_life_en, v.source_pt, v.source_en, 'published'
FROM public.drugs d
JOIN (VALUES
  ('acenocumarol',
   E'Anticoagulante de ação indireta: reduz a síntese hepática dos fatores II, VII, IX e X da coagulação por antagonismo da vitamina K; sem efeito anticoagulante in vitro. Efeito aparente apenas após depleção plasmática dos fatores (2-3 dias); controlo pelo INR (Prontuário 4.3.1.2).',
   E'Indirect anticoagulant: reduces the hepatic synthesis of coagulation factors II, VII, IX and X by antagonising vitamin K; no in vitro anticoagulant effect. Effect apparent only after plasma depletion of the factors (2-3 days); monitored by INR (Prontuário 4.3.1.2).',
   E'Antagonismo da vitamina K (fitomenadiona) — inibição da gama-carboxilação dos fatores da coagulação dependentes da vitamina K.',
   E'Antagonism of vitamin K (phytonadione) — inhibition of gamma-carboxylation of vitamin K-dependent clotting factors.',
   E'As interações decorrem de alterações do metabolismo (aumento, ex: carbamazepina; diminuição, ex: cimetidina), do aumento do risco hemorrágico por ação antiagregante (ex: ácido acetilsalicílico) ou por potenciação da ação anticoagulante (AINEs, antihormonas, antiarrítmicos e outros) (Prontuário 4.3.1.2). O EMC-UK regista inibição ou indução do CYP2C9 como mecanismo principal de interação.',
   E'Interactions arise from altered metabolism (increase, e.g. carbamazepine; decrease, e.g. cimetidine), increased bleeding risk from antiplatelet action (e.g. acetylsalicylic acid) or potentiation of the anticoagulant action (NSAIDs, antihormones, antiarrhythmics and others) (Prontuário 4.3.1.2). EMC-UK records inhibition or induction of CYP2C9 as the main interaction mechanism.',
   E'Derivado cumarínico oral; biodisponibilidade completa por via oral. O efeito depende da função hepática (síntese de fatores) e da disponibilidade de vitamina K (dieta).',
   E'Oral coumarin derivative; complete oral bioavailability. The effect depends on hepatic function (factor synthesis) and vitamin K availability (diet).',
   E'Meia-vida mais curta que a da varfarina (regime diário); o EMC-UK remete para o controlo frequente do INR (2×/semana ao iniciar ou retirar um fármaco concomitante).',
   E'Shorter half-life than warfarin (daily regimen); EMC-UK refers to frequent INR monitoring (twice weekly when starting or withdrawing a concomitant drug).',
   'EMC-UK — Sinthrome 1 mg Tablets SmPC (5.2 Pharmacokinetic properties): https://www.medicines.org.uk/emc/product/2058 ; Prontuário Terapêutico do INFARMED (11.ª ed., 2012) — 4.3.1.2',
   'EMC-UK — Sinthrome 1 mg Tablets SmPC (5.2 Pharmacokinetic properties): https://www.medicines.org.uk/emc/product/2058 ; Prontuário Terapêutico do INFARMED (11th ed., 2012) — 4.3.1.2'),

  ('eslicarbazepina',
   E'Anticonvulsivante: inibição dos canais de sódio dependentes de voltagem (mecanismo presumido do metabolito ativo eslicarbazepina); farmacocinética linear e proporcional à dose (400-1600 mg/dia), estado estacionário em 4-5 dias (rótulo FDA 12.1/12.3).',
   E'Anticonvulsant: inhibition of voltage-gated sodium channels (presumed mechanism of the active metabolite eslicarbazepine); linear, dose-proportional pharmacokinetics (400-1600 mg/day), steady state in 4-5 days (FDA label 12.1/12.3).',
   E'Inibição dos canais de sódio dependentes de voltagem; inibição do CYP2C19 e indução do CYP3A4 (relevante para interações).',
   E'Inhibition of voltage-gated sodium channels; CYP2C19 inhibition and CYP3A4 induction (relevant for interactions).',
   E'Metabolismo: conversão extensa em eslicarbazepina (metabolito ativo); eliminação principalmente por glucuronidação e excreção renal.',
   E'Metabolism: extensive conversion to eslicarbazepine (active metabolite); elimination mainly by glucuronidation and renal excretion.',
   E'Absorção oral rápida e bem absorvida; a maioria da dose administrada é convertida em eslicarbazepina.',
   E'Rapid oral absorption and well absorbed; most of the administered dose is converted to eslicarbazepine.',
   E'Meia-vida aparente da eslicarbazepina no plasma: 13-20 horas em doentes adultos com epilepsia (rótulo FDA 12.3).',
   E'Apparent plasma half-life of eslicarbazepine: 13-20 hours in adult epilepsy patients (FDA label 12.3).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Eslicarbazepina, secção 12: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=22d08671-ac0d-4e3d-8195-929bbb021125',
   'DailyMed/FDA (NIH/NLM) — approved Eslicarbazepine label, section 12: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=22d08671-ac0d-4e3d-8195-929bbb021125'),

  ('cimetidina',
   E'Antiulceroso: antagonista dos recetores H2 — reduz a secreção ácida gástrica basal e estimulada, incluindo a secreção noturna e após refeições (rótulo FDA).',
   E'Antiulcer: H2-receptor antagonist — reduces basal and stimulated gastric acid secretion, including nocturnal and post-meal secretion (FDA label).',
   E'Bloqueio competitivo dos recetores H2 da histamina nas células parietais gástricas; inibição dose-dependente das enzimas do citocromo P450 (CYP1A2, CYP2C9, CYP2D6, CYP3A4) — base das interações farmacocinéticas.',
   E'Competitive blockade of histamine H2 receptors on gastric parietal cells; dose-dependent inhibition of cytochrome P450 enzymes (CYP1A2, CYP2C9, CYP2D6, CYP3A4) — the basis of pharmacokinetic interactions.',
   E'Extensamente metabolizada (o sulfóxido é o principal metabolito); excreção renal do fármaco e metabolitos (48% da dose recuperada na urina em 24 h após dose oral única).',
   E'Extensively metabolised (the sulfoxide is the main metabolite); renal excretion of the drug and metabolites (48% of a single oral dose recovered in urine within 24 h).',
   E'Absorção oral rápida; picos plasmáticos em 45-90 minutos após administração oral (rótulo FDA Pharmacokinetics).',
   E'Rapid oral absorption; peak plasma levels 45-90 minutes after oral administration (FDA label Pharmacokinetics).',
   E'Meia-vida de aproximadamente 2 horas; as concentrações mantêm-se acima do necessário para 80% de inibição da secreção ácida basal durante 4-5 horas após 300 mg.',
   E'Half-life of approximately 2 hours; concentrations remain above those required for 80% inhibition of basal gastric acid secretion for 4-5 hours after 300 mg.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Cimetidina, secção Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=06c0a509-026f-44e0-9975-a94a8de51d43',
   'DailyMed/FDA (NIH/NLM) — approved Cimetidine label, Pharmacokinetics section: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=06c0a509-026f-44e0-9975-a94a8de51d43'),

  ('cloranfenicol',
   E'Antibiótico bacteriostático de largo espetro: inibição da síntese proteica bacteriana por ligação à subunidade 50S do ribossoma. Uso restrito a infeções graves (rótulo FDA).',
   E'Broad-spectrum bacteriostatic antibiotic: inhibition of bacterial protein synthesis by binding to the 50S ribosomal subunit. Use restricted to serious infections (FDA label).',
   E'Inibição da peptidiltransferase (subunidade 50S) — bloqueia a síntese proteica bacteriana.',
   E'Inhibition of peptidyltransferase (50S subunit) — blocks bacterial protein synthesis.',
   E'O rótulo não detalha o metabolismo; o fármaco é metabolizado no fígado (conjugação com ácido glucurónico) e eliminado por via renal.',
   E'The label does not detail metabolism; the drug is metabolised in the liver (glucuronic acid conjugation) and eliminated renally.',
   E'Forma IV (succinato sódico) para uso hospitalar; também disponível por via oral em preparações (palmitato). O rótulo refere atravessar a barreira placentar após administração oral.',
   E'IV form (sodium succinate) for hospital use; also available orally (palmitate preparations). The label notes it crosses the placental barrier after oral administration.',
   E'Meia-vida não detalhada no rótulo; a excreção renal é a principal via (recuperação de metabolitos na urina).',
   E'Half-life not detailed in the label; renal excretion is the main route (metabolite recovery in urine).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Cloranfenicol (FRESENIUS KABI): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=aed29594-211d-49ef-813f-131975a8d0e3',
   'DailyMed/FDA (NIH/NLM) — approved Chloramphenicol label (FRESENIUS KABI): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=aed29594-211d-49ef-813f-131975a8d0e3'),

  ('dissulfiram',
   E'Anti-alcoólico: inibição irreversível da aldeído desidrogenase — após ingestão de álcool, a acumulação de acetaldeído provoca a reação dissulfiram-álcool (rubor, taquicardia, hipotensão, náuseas/vómitos) que desencoraja o consumo (rótulo FDA).',
   E'Alcohol deterrent: irreversible inhibition of aldehyde dehydrogenase — after alcohol intake, acetaldehyde accumulation causes the disulfiram-alcohol reaction (flushing, tachycardia, hypotension, nausea/vomiting) that discourages consumption (FDA label).',
   E'Inibição da aldeído desidrogenase (acumulação de acetaldeído); diminuição da taxa de metabolismo de certos fármacos (aumento dos seus níveis e risco de toxicidade).',
   E'Inhibition of aldehyde dehydrogenase (acetaldehyde accumulation); decreased metabolism rate of certain drugs (increased levels and toxicity risk).',
   E'Metabolizado a dietilditiocarbamato; a excreção é mista (urina e ar expirado). O rótulo não detalha percentagens.',
   E'Metabolised to diethyldithiocarbamate; excretion is mixed (urine and expired air). The label does not detail percentages.',
   E'Absorção oral; o efeito depende da ingestão concomitante de álcool (o fármaco não tem efeito na sobriedade sem a reação ao álcool).',
   E'Oral absorption; the effect depends on concomitant alcohol intake (the drug has no effect on sobriety without the alcohol reaction).',
   E'Meia-vida não documentada no rótulo; o efeito sobre a aldeído desidrogenase é prolongado (a reação pode ocorrer até dias após a última dose).',
   E'Half-life not documented in the label; the effect on aldehyde dehydrogenase is prolonged (the reaction may occur up to days after the last dose).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Dissulfiram (ALVOGEN): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b90f8ff4-4fb3-46ab-8149-cb55f24a4044',
   'DailyMed/FDA (NIH/NLM) — approved Disulfiram label (ALVOGEN): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b90f8ff4-4fb3-46ab-8149-cb55f24a4044'),

  ('ertapenem',
   E'Carbapenemo bactericida: inibição da síntese da parede celular bacteriana; estável a muitas beta-lactamases, incluindo ESBL. Concentrações plasmáticas médias após 1 g IV/IM apresentadas na secção 12.3 do rótulo (pico ~155 mcg/mL a 0,5 h após infusão IV).',
   E'Bactericidal carbapenem: inhibition of bacterial cell wall synthesis; stable to many beta-lactamases, including ESBLs. Mean plasma concentrations after 1 g IV/IM presented in label section 12.3 (peak ~155 mcg/mL at 0.5 h after IV infusion).',
   E'Inibição da síntese da parede celular bacteriana (ligação às PBP) — bactericida.',
   E'Inhibition of bacterial cell wall synthesis (PBP binding) — bactericidal.',
   E'Metabolismo: hidrólise do anel beta-lactâmico ao metabolito inativo (abertura do anel), sem participação relevante do CYP.',
   E'Metabolism: hydrolysis of the beta-lactam ring to the inactive metabolite (ring opening), with no relevant CYP involvement.',
   E'Administração iv/im; distribuição ampla nos tecidos. A co-administração com probenecida inibe a secreção tubular ativa e aumenta as concentrações (7.1).',
   E'IV/IM administration; wide tissue distribution. Co-administration with probenecid inhibits active tubular secretion and increases concentrations (7.1).',
   E'Meia-vida plasmática de aproximadamente 4 horas em adultos jovens saudáveis (dados da secção 12.3).',
   E'Plasma half-life of approximately 4 hours in healthy young adults (section 12.3 data).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Ertapenem (INVANZ, MERCK), secção 12: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=33f3b99b-fa82-42e0-26bf-f49891ae3d22',
   'DailyMed/FDA (NIH/NLM) — approved Ertapenem label (INVANZ, MERCK), section 12: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=33f3b99b-fa82-42e0-26bf-f49891ae3d22'),

  ('indacaterol',
   E'Broncodilatador de longa duração (uma toma diária): ativação dos recetores beta-2 no músculo liso brônquico; usado na manutenção da DPOC e da asma (Prontuário 5.1.1).',
   E'Long-acting bronchodilator (once daily): activation of beta-2 receptors on bronchial smooth muscle; used for maintenance of COPD and asthma (Prontuário 5.1.1).',
   E'Agonista seletivo dos recetores beta-2 adrenérgicos (broncodilatação); o QUADRO 2 regista inibição dos CYP3A4/P-gp como interação (aumenta os níveis plasmáticos até 2×).',
   E'Selective beta-2 adrenergic receptor agonist (bronchodilation); QUADRO 2 records CYP3A4/P-gp inhibition as an interaction (increases plasma levels up to 2-fold).',
   E'Metabolismo principalmente pelo CYP3A4 (substrato); também substrato da P-gp (QUADRO 2 do Anexo 7).',
   E'Metabolism mainly by CYP3A4 (substrate); also a P-gp substrate (QUADRO 2 of Annex 7).',
   E'Administração por inalação (pó para inalação, cápsulas — Hirobriz/Onbrez); a absorção é pulmonar.',
   E'Inhalation administration (powder for inhalation, capsules — Hirobriz/Onbrez); absorption is pulmonary.',
   E'Duração de ação ≥ 24 horas (uma toma diária) — longa duração de ação (Prontuário 5.1.1).',
   E'Duration of action ≥ 24 hours (once daily) — long duration of action (Prontuário 5.1.1).',
   'Prontuário Terapêutico do INFARMED (11.ª ed., 2012) — 5.1.1 e QUADRO 2 do Anexo 7 (Indacaterol)',
   'Prontuário Terapêutico do INFARMED (11th ed., 2012) — 5.1.1 and QUADRO 2 of Annex 7 (Indacaterol)'),

  ('ivabradina',
   E'Inibidor seletivo do canal If: redução da frequência cardíaca dependente da dose, sem efeito na condução intracardíaca, contractilidade ou repolarização (rótulo FDA).',
   E'Selective If channel inhibitor: dose-dependent heart rate reduction, without effects on intracardiac conduction, contractility or repolarisation (FDA label).',
   E'Inibição seletiva do canal If do nó sinusal (corrente de pacemaker) — cronotropismo negativo puro.',
   E'Selective inhibition of the sinus node If channel (pacemaker current) — pure negative chronotropy.',
   E'Metabolismo extenso pelo CYP3A4 (substrato) — inibidores aumentam a exposição (bradicardia/perturbações de condução) e indutores diminuem (7.1).',
   E'Extensive CYP3A4 metabolism (substrate) — inhibitors increase exposure (bradycardia/conduction disturbances) and inducers decrease it (7.1).',
   E'Absorção oral rápida e quase completa; a biodisponibilidade é de aproximadamente 40% devido ao metabolismo de primeira passagem (12.3).',
   E'Rapid and almost complete oral absorption; bioavailability is approximately 40% due to first-pass metabolism (12.3).',
   E'Meia-vida efetiva de aproximadamente 6 horas (2 horas para a atividade plasmática) (12.3).',
   E'Effective half-life of approximately 6 hours (2 hours for plasma activity) (12.3).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Ivabradina (CORLANOR, AMGEN), secção 12: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=92018a65-38f6-45f7-91d4-a34921b81d0d',
   'DailyMed/FDA (NIH/NLM) — approved Ivabradine label (CORLANOR, AMGEN), section 12: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=92018a65-38f6-45f7-91d4-a34921b81d0d'),

  ('levodopa',
   E'Precursor da dopamina: atravessa a barreira hematoencefálica e é descarboxilado em dopamina no cérebro; a carbidopa reduz a dose necessária em ~75% e aumenta os níveis plasmáticos e a meia-vida da levodopa (rótulo SINEMET Pharmacokinetics).',
   E'Dopamine precursor: crosses the blood-brain barrier and is decarboxylated to dopamine in the brain; carbidopa reduces the required dose by ~75% and increases levodopa plasma levels and half-life (SINEMET label Pharmacokinetics).',
   E'Descarboxilação da levodopa em dopamina (DOPA descarboxilase) — reposição dopaminérgica central; a carbidopa inibe a descarboxilase periférica.',
   E'Decarboxylation of levodopa to dopamine (DOPA decarboxylase) — central dopaminergic replenishment; carbidopa inhibits peripheral decarboxylase.',
   E'Metabolizada por descarboxilação e O-metilação (COMT); a carbidopa aumenta a meia-vida plasmática da levodopa de ~50 min para ~1,5 h.',
   E'Metabolised by decarboxylation and O-methylation (COMT); carbidopa increases the plasma half-life of levodopa from ~50 min to ~1.5 h.',
   E'Absorção oral; os sais de ferro formam quelatos com a levodopa e a carbidopa, reduzindo a biodisponibilidade (Drug Interactions).',
   E'Oral absorption; iron salts form chelates with levodopa and carbidopa, reducing bioavailability (Drug Interactions).',
   E'Meia-vida plasmática da levodopa: ~50 minutos sem carbidopa; ~1,5 horas com carbidopa (rótulo SINEMET Pharmacokinetics).',
   E'Plasma half-life of levodopa: ~50 minutes without carbidopa; ~1.5 hours with carbidopa (SINEMET label Pharmacokinetics).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Sinemet (ORGANON LLC), secção Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9b17b028-964a-473c-823d-81423535bd66',
   'DailyMed/FDA (NIH/NLM) — approved Sinemet label (ORGANON LLC), Pharmacokinetics section: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9b17b028-964a-473c-823d-81423535bd66'),

  ('ticagrelor',
   E'Antiagregante plaquetário: inibição reversível do recetor P2Y12 do ADP — impede a ativação e agregação plaquetária; o metabolito ativo é aproximadamente equipotente (rótulo FDA 12.1).',
   E'Antiplatelet: reversible inhibition of the platelet P2Y12 ADP receptor — prevents platelet activation and aggregation; the active metabolite is approximately equipotent (FDA label 12.1).',
   E'Inibição reversível e direta do recetor P2Y12 (sem necessidade de ativação metabólica para o efeito antiagregante).',
   E'Direct and reversible inhibition of the P2Y12 receptor (no metabolic activation required for the antiplatelet effect).',
   E'Metabolismo pelo CYP3A4/3A5 ao metabolito ativo AR-C124910XX (equipotente); substrato e inibidor moderado do CYP3A4 (7.1/7.2).',
   E'Metabolism by CYP3A4/3A5 to the active metabolite AR-C124910XX (equipotent); CYP3A4 substrate and moderate inhibitor (7.1/7.2).',
   E'Absorção: Tmax mediano de 1,5 h (intervalo 1,0-4,0); biodisponibilidade absoluta média de ~36% (intervalo 30-42%); pode ser tomado com ou sem alimentos (12.3).',
   E'Absorption: median Tmax of 1.5 h (range 1.0-4.0); mean absolute bioavailability of ~36% (range 30-42%); may be taken with or without food (12.3).',
   E'Meia-vida do ticagrelor de aproximadamente 7 horas; do metabolito ativo de aproximadamente 9 horas (12.3).',
   E'Half-life of ticagrelor of approximately 7 hours; of the active metabolite approximately 9 hours (12.3).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Ticagrelor (BRILINTA, ASTRAZENECA), secção 12: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f7b3f443-e83d-4bf2-0e96-023448fed9a8',
   'DailyMed/FDA (NIH/NLM) — approved Ticagrelor label (BRILINTA, ASTRAZENECA), section 12: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f7b3f443-e83d-4bf2-0e96-023448fed9a8'),

  ('diltiazem',
   E'Bloqueador dos canais de cálcio (benzotiazepina): inibição do influxo de cálcio no miocárdio e músculo liso vascular — redução da contractilidade, condução AV e resistência vascular; anti-hipertensor e antianginoso (rótulo TIAZAC).',
   E'Calcium channel blocker (benzothiazepine): inhibition of calcium influx in the myocardium and vascular smooth muscle — reduced contractility, AV conduction and vascular resistance; antihypertensive and antianginal (TIAZAC label).',
   E'Bloqueio dos canais de cálcio tipo L; substrato e inibidor da P-gp e do CYP3A4.',
   E'L-type calcium channel blockade; P-gp and CYP3A4 substrate and inhibitor.',
   E'Metabolismo hepático extenso de primeira passagem; substrato e inibidor do CYP3A4 — interage com midazolam/triazolam, ciclosporina, carbamazepina e estatinas (Drug Interactions).',
   E'Extensive first-pass hepatic metabolism; CYP3A4 substrate and inhibitor — interacts with midazolam/triazolam, cyclosporine, carbamazepine and statins (Drug Interactions).',
   E'Absorção gastrointestinal bem absorvida; biodisponibilidade oral de ~40% (formulação de libertação imediata); apenas 2-4% do fármaco inalterado na urina (Pharmacokinetics and Metabolism).',
   E'Well absorbed from the GI tract; oral bioavailability of ~40% (immediate-release formulation); only 2-4% of unchanged drug in urine (Pharmacokinetics and Metabolism).',
   E'Meia-vida de eliminação plasmática de aproximadamente 3,0-4,5 horas (formulação de libertação imediata).',
   E'Plasma elimination half-life of approximately 3.0-4.5 hours (immediate-release formulation).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Diltiazem (TIAZAC ER, BAUSCH HEALTH), secção Pharmacokinetics and Metabolism: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c567fe7e-887e-4291-a0d1-2dd3f25cbf25',
   'DailyMed/FDA (NIH/NLM) — approved Diltiazem label (TIAZAC ER, BAUSCH HEALTH), Pharmacokinetics and Metabolism section: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c567fe7e-887e-4291-a0d1-2dd3f25cbf25'),

  ('verapamilo',
   E'Bloqueador dos canais de cálcio (fenilalquilamina): efeitos cronotrópico e dromotrópico negativos (retarda a condução AV) e vasodilatação arterial — anti-hipertensor, antianginoso e antiarrítmico classe IV (rótulo VERAPAMIL ER).',
   E'Calcium channel blocker (phenylalkylamine): negative chronotropic and dromotropic effects (slows AV conduction) and arterial vasodilation — antihypertensive, antianginal and class IV antiarrhythmic (VERAPAMIL ER label).',
   E'Bloqueio dos canais de cálcio tipo L; substrato do CYP3A4 e inibidor da P-gp.',
   E'L-type calcium channel blockade; CYP3A4 substrate and P-gp inhibitor.',
   E'Metabolismo hepático extenso de primeira passagem (CYP3A4); a rifampicina reduz marcadamente a biodisponibilidade oral e o fenobarbital aumenta o clearance (Drug Interactions).',
   E'Extensive first-pass hepatic metabolism (CYP3A4); rifampin markedly reduces oral bioavailability and phenobarbital increases clearance (Drug Interactions).',
   E'Absorção oral; a biodisponibilidade é limitada pelo efeito de primeira passagem (formas ER).',
   E'Oral absorption; bioavailability is limited by first-pass effect (ER forms).',
   E'Meia-vida de eliminação variável (aprox. 2,8-7,4 h nas formas orais, conforme a formulação).',
   E'Elimination half-life variable (approx. 2.8-7.4 h for oral forms, depending on formulation).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Verapamilo (NIVAGEN), secção Drug Interactions/Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e36e485f-fbed-4e30-9a63-984931f2e54e',
   'DailyMed/FDA (NIH/NLM) — approved Verapamil label (NIVAGEN), Drug Interactions/Pharmacokinetics section: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e36e485f-fbed-4e30-9a63-984931f2e54e'),

  ('tacrolimus',
   E'Imunossupressor (inibidor da calcineurina): liga-se à FKBP-12 e o complexo inibe a calcineurina, bloqueando a ativação dos linfócitos T; substrato do CYP3A4/3A5 e da P-gp, com janela terapêutica estreita (rótulo PROGRAF 12.1).',
   E'Immunosuppressant (calcineurin inhibitor): binds FKBP-12 and the complex inhibits calcineurin, blocking T-lymphocyte activation; CYP3A4/3A5 and P-gp substrate, with a narrow therapeutic window (PROGRAF label 12.1).',
   E'Inibição da calcineurina (via complexo com FKBP-12) — impede a desfosforilação/translocação do NFAT e a ativação dos linfócitos T.',
   E'Calcineurin inhibition (via FKBP-12 complex) — prevents NFAT dephosphorylation/translocation and T-lymphocyte activation.',
   E'Metabolismo extenso pelo CYP3A4/3A5 (substrato); inibidores do CYP3A4/P-gp aumentam os níveis e indutores diminuem (7.2).',
   E'Extensive CYP3A4/3A5 metabolism (substrate); CYP3A4/P-gp inhibitors increase levels and inducers decrease them (7.2).',
   E'Absorção oral variável (influenciada pelos alimentos); biodisponibilidade oral de aproximadamente 17-25% (dados da secção 12.3).',
   E'Variable oral absorption (food-influenced); oral bioavailability of approximately 17-25% (section 12.3 data).',
   E'Meia-vida de eliminação de aproximadamente 11-19 horas em adultos (12.3).',
   E'Elimination half-life of approximately 11-19 hours in adults (12.3).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Tacrolimus (PROGRAF, ASTELLAS), secção 12: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7f667de1-9dfa-4bd6-8ba0-15ee2d78873b',
   'DailyMed/FDA (NIH/NLM) — approved Tacrolimus label (PROGRAF, ASTELLAS), section 12: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7f667de1-9dfa-4bd6-8ba0-15ee2d78873b'),

  ('sirolimus',
   E'Imunossupressor (inibidor do mTOR): bloqueia a ativação e proliferação dos linfócitos T e a produção de anticorpos — mecanismo distinto de outros imunossupressores; substrato do CYP3A4 e da P-gp (rótulo FDA 12.1/7).',
   E'Immunosuppressant (mTOR inhibitor): blocks T-lymphocyte activation and proliferation and antibody production — a mechanism distinct from other immunosuppressants; CYP3A4 and P-gp substrate (FDA label 12.1/7).',
   E'Inibição do mTOR (via complexo com FKBP-12) — bloqueio da transdução de sinal dos recetores de citocinas nos linfócitos T.',
   E'mTOR inhibition (via FKBP-12 complex) — blockade of cytokine receptor signal transduction in T lymphocytes.',
   E'Metabolismo pelo CYP3A4 (substrato); a ciclosporina (inibidor do CYP3A4/P-gp) aumenta as concentrações — administrar sirolimus 4 h após a ciclosporina (7.1).',
   E'CYP3A4 metabolism (substrate); cyclosporine (CYP3A4/P-gp inhibitor) increases concentrations — administer sirolimus 4 h after cyclosporine (7.1).',
   E'Absorção oral; o rótulo recomenda administração consistente com ou sem alimentos (tabela 4 da secção 12.3).',
   E'Oral absorption; the label recommends consistent administration with or without food (Table 4, section 12.3).',
   E'Meia-vida longa de aproximadamente 57-63 horas (12.3).',
   E'Long half-life of approximately 57-63 hours (12.3).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Sirolimus (MYLAN), secção 12: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5908cd1a-fc5a-462f-99ed-1d8983e253c9',
   'DailyMed/FDA (NIH/NLM) — approved Sirolimus label (MYLAN), section 12: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5908cd1a-fc5a-462f-99ed-1d8983e253c9'),

  ('micofenolato',
   E'Imunossupressor: o MMF é hidrolisado em MPA (metabolito ativo), inibidor seletivo da IMPDH — bloqueia a síntese de novo de guanosina e a proliferação de linfócitos (rótulo CELLCEPT 12.1).',
   E'Immunosuppressant: MMF is hydrolysed to MPA (active metabolite), a selective IMPDH inhibitor — blocks de novo guanosine synthesis and lymphocyte proliferation (CELLCEPT label 12.1).',
   E'Inibição não competitiva e seletiva da IMPDH (tipo I e II) — bloqueio da via de novo da síntese de nucleótidos de guanina e da síntese de ADN.',
   E'Selective uncompetitive inhibition of IMPDH (types I and II) — blockade of the de novo pathway of guanine nucleotide synthesis and DNA synthesis.',
   E'Metabolismo: conversão completa do MMF em MPA (metabolito ativo); metabolização hepática do MPA (glucuronidação) e excreção renal do glucurónido.',
   E'Metabolism: complete conversion of MMF to MPA (active metabolite); hepatic metabolism of MPA (glucuronidation) and renal excretion of the glucuronide.',
   E'Absorção oral: biodisponibilidade absoluta média do MMF oral de 94% (relativa ao IV) (12.3); antiácidos com Mg/Al e IBP reduzem a exposição ao MPA (7.1).',
   E'Oral absorption: mean absolute bioavailability of oral MMF of 94% (relative to IV) (12.3); antacids with Mg/Al and PPIs reduce MPA exposure (7.1).',
   E'Meia-vida do MPA de aproximadamente 11-18 horas (dados da secção 12.3).',
   E'Half-life of MPA of approximately 11-18 hours (section 12.3 data).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Micofenolato (CELLCEPT, GENENTECH), secção 12: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=37241e87-4af4-4dc3-a1aa-ea6f20d8dc40',
   'DailyMed/FDA (NIH/NLM) — approved Mycophenolate label (CELLCEPT, GENENTECH), section 12: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=37241e87-4af4-4dc3-a1aa-ea6f20d8dc40'),

  ('pimozida',
   E'Antipsicótico (difenilbutilpiperidina): antagonista dopaminérgico D2 — reduz os tiques na síndrome de Tourette; prolonga o intervalo QT (efeito aditivo com outros fármacos que prolongam o QT) (rótulo FDA).',
   E'Antipsychotic (diphenylbutylpiperidine): dopaminergic D2 antagonist — reduces tics in Tourette syndrome; prolongs the QT interval (additive effect with other QT-prolonging drugs) (FDA label).',
   E'Bloqueio dos recetores dopaminérgicos D2; prolongamento do QT (bloqueio dos canais de potássio cardíacos).',
   E'Dopaminergic D2 receptor blockade; QT prolongation (cardiac potassium channel blockade).',
   E'Metabolismo principalmente pelo CYP3A4 (também CYP1A2 e CYP2D6); metabolizadores fracos do CYP2D6 (5-10% da população) têm concentrações mais altas (Pharmacogenomics).',
   E'Metabolism mainly by CYP3A4 (also CYP1A2 and CYP2D6); poor CYP2D6 metabolisers (5-10% of the population) have higher concentrations (Pharmacogenomics).',
   E'Absorção oral; o rótulo não quantifica a biodisponibilidade (uso em comprimidos).',
   E'Oral absorption; the label does not quantify bioavailability (tablet use).',
   E'Meia-vida de eliminação longa (aproximadamente 50 horas).',
   E'Long elimination half-life (approximately 50 hours).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Pimozida (ANI PHARMACEUTICALS): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4e954fc2-fdff-486c-beb6-2b8ace717081',
   'DailyMed/FDA (NIH/NLM) — approved Pimozide label (ANI PHARMACEUTICALS): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4e954fc2-fdff-486c-beb6-2b8ace717081')
) AS v(slug, pharmacodynamics_pt, pharmacodynamics_en, mechanism_pt, mechanism_en,
        metabolism_pt, metabolism_en, absorption_pt, absorption_en,
        half_life_pt, half_life_en, source_pt, source_en)
ON d.slug = v.slug
ON CONFLICT (drug_id) DO NOTHING;

-- =====================================================================
-- 4. Gravidez (drug_pregnancy_info) — sempre preenchida (17.3)
-- =====================================================================
INSERT INTO public.drug_pregnancy_info
  (drug_id, pregnancy_category, risk_pt, risk_en, trimester_pt, trimester_en,
   lactation_pt, lactation_en, contraception_pt, contraception_en,
   source_pt, source_en, status)
SELECT d.id, v.pregnancy_category, v.risk_pt, v.risk_en, v.trimester_pt, v.trimester_en,
       v.lactation_pt, v.lactation_en, v.contraception_pt, v.contraception_en,
       v.source_pt, v.source_en, 'published'
FROM public.drugs d
JOIN (VALUES
  ('acenocumarol', 'contraindicated',
   E'Os cumarínicos (acenocumarol e varfarina) são contraindicados durante o primeiro trimestre (são teratogénicos) e nas últimas semanas de gravidez (risco de hemorragia fetal ou placentar) (Prontuário 4.3.1.2).',
   E'The coumarins (acenocoumarol and warfarin) are contraindicated during the first trimester (teratogenic) and in the last weeks of pregnancy (risk of fetal or placental haemorrhage) (Prontuário 4.3.1.2).',
   E'Contraindicado no 1.º trimestre (teratogénico) e nas últimas semanas (hemorragia fetal/placentar); alternativa: heparina (que não atravessa a placenta).',
   E'Contraindicated in the 1st trimester (teratogenic) and in the last weeks (fetal/placental haemorrhage); alternative: heparin (does not cross the placenta).',
   E'Sem dados específicos no Prontuário sobre o aleitamento; a classe dos cumarínicos exige avaliação caso a caso.',
   E'No specific Prontuário data on breastfeeding; the coumarin class requires case-by-case evaluation.',
   E'Ponderar o risco na gravidez antes da terapêutica em mulheres em idade fértil (contraceção recomendada).',
   E'Weigh the pregnancy risk before therapy in women of childbearing potential (contraception recommended).',
   'Prontuário Terapêutico do INFARMED (11.ª ed., 2012) — Anticoagulantes orais, 4.3.1.2 ; EMC-UK Sinthrome 4.6',
   'Prontuário Terapêutico do INFARMED (11th ed., 2012) — Oral anticoagulants, 4.3.1.2 ; EMC-UK Sinthrome 4.6'),

  ('eslicarbazepina', 'caution',
   E'Rótulo FDA (8.1): existe um registo de exposição na gravidez que monitoriza os resultados em mulheres expostas a antiepiléticos (NAAED Pregnancy Registry). Os antiepiléticos, no geral, aumentam o risco de malformações congénitas; o risco não está quantificado no rótulo da eslicarbazepina.',
   E'FDA label (8.1): there is a pregnancy exposure registry that monitors outcomes in women exposed to antiepileptics (NAAED Pregnancy Registry). Antiepileptics in general increase the risk of congenital malformations; the risk is not quantified in the eslicarbazepine label.',
   E'Risco potencial (classe dos antiepiléticos); encorajar a inscrição no registo de gravidez (NAAED).',
   E'Potential risk (antiepileptic class); encourage enrolment in the pregnancy registry (NAAED).',
   E'Sem dados específicos sobre o aleitamento no rótulo (secção 8.2 não detalhada na extração); avaliar risco/benefício.',
   E'No specific breastfeeding data in the label (section 8.2 not detailed in extraction); assess risk/benefit.',
   E'Recomendar aconselhamento sobre contraceção e planeamento da gravidez a mulheres em idade fértil.',
   E'Advise contraception and pregnancy planning counselling in women of childbearing potential.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Eslicarbazepina, secção 8.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=22d08671-ac0d-4e3d-8195-929bbb021125',
   'DailyMed/FDA (NIH/NLM) — approved Eslicarbazepine label, section 8.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=22d08671-ac0d-4e3d-8195-929bbb021125'),

  ('cimetidina', 'caution',
   E'Rótulo FDA (Pregnancy, Categoria B): estudos de reprodução em ratos, coelhos e murganhos até 40× a dose humana normal sem evidência de compromisso da fertilidade ou dano fetal; sem estudos adequados e bem controlados em grávidas — usar apenas se claramente necessário.',
   E'FDA label (Pregnancy, Category B): reproduction studies in rats, rabbits and mice at up to 40× the normal human dose with no evidence of impaired fertility or fetal harm; no adequate and well-controlled studies in pregnant women — use only if clearly needed.',
   E'Categoria B: usar apenas se claramente necessário (sem estudos adequados em grávidas).',
   E'Category B: use only if clearly needed (no adequate studies in pregnant women).',
   E'O rótulo não detalha a excreção no leite materno; a cimetidina é excretada no leite humano (dados de literatura).',
   E'The label does not detail excretion in breast milk; cimetidine is excreted in human milk (literature data).',
   E'Não aplicável (sem requisitos específicos de contraceção no rótulo).',
   E'Not applicable (no specific contraception requirements in the label).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Cimetidina, secção Pregnancy: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=06c0a509-026f-44e0-9975-a94a8de51d43',
   'DailyMed/FDA (NIH/NLM) — approved Cimetidine label, Pregnancy section: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=06c0a509-026f-44e0-9975-a94a8de51d43'),

  ('cloranfenicol', 'caution',
   E'Rótulo FDA (Pregnancy, Categoria C): sem estudos de reprodução animal e sem estudos adequados em grávidas; atravessa a barreira placentar — usar apenas se o benefício potencial justificar o risco (potencial de efeitos tóxicos no feto, incluindo Gray syndrome).',
   E'FDA label (Pregnancy, Category C): no animal reproduction studies and no adequate studies in pregnant women; crosses the placental barrier — use only if the potential benefit justifies the risk (potential fetal toxic effects, including Gray syndrome).',
   E'Categoria C: usar apenas se o benefício justificar o risco (atravessa a placenta).',
   E'Category C: use only if benefit justifies risk (crosses the placenta).',
   E'Excretado no leite humano após administração oral — risco de reações adversas graves no lactente (Gray syndrome); decidir entre suspender o aleitamento ou o fármaco (Nursing Mothers).',
   E'Excreted in human milk after oral administration — risk of serious adverse reactions in the infant (Gray syndrome); decide between discontinuing nursing or the drug (Nursing Mothers).',
   E'Não aplicável (sem requisitos específicos de contraceção no rótulo).',
   E'Not applicable (no specific contraception requirements in the label).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Cloranfenicol, secção Pregnancy/Nursing Mothers: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=aed29594-211d-49ef-813f-131975a8d0e3',
   'DailyMed/FDA (NIH/NLM) — approved Chloramphenicol label, Pregnancy/Nursing Mothers section: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=aed29594-211d-49ef-813f-131975a8d0e3'),

  ('dissulfiram', 'caution',
   E'Rótulo FDA (Usage in Pregnancy): a segurança na gravidez não foi estabelecida — usar apenas se, no julgamento do médico, os benefícios prováveis superarem os riscos possíveis.',
   E'FDA label (Usage in Pregnancy): safety in pregnancy has not been established — use only if, in the physician\'s judgement, the probable benefits outweigh the possible risks.',
   E'Usar apenas se o benefício provável superar os riscos possíveis (segurança não estabelecida).',
   E'Use only if the probable benefit outweighs the possible risks (safety not established).',
   E'Não se sabe se é excretado no leite humano; não administrar a mães a amamentar (Nursing Mothers).',
   E'It is not known whether it is excreted in human milk; do not give to nursing mothers (Nursing Mothers).',
   E'Não aplicável (sem requisitos específicos de contraceção no rótulo).',
   E'Not applicable (no specific contraception requirements in the label).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Dissulfiram, secções Usage in Pregnancy/Nursing Mothers: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b90f8ff4-4fb3-46ab-8149-cb55f24a4044',
   'DailyMed/FDA (NIH/NLM) — approved Disulfiram label, Usage in Pregnancy/Nursing Mothers sections: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b90f8ff4-4fb3-46ab-8149-cb55f24a4044'),

  ('ertapenem', 'caution',
   E'Rótulo FDA (8.1): dados disponíveis de um pequeno número de casos pós-comercialização insuficientes para informar o risco; em estudos de reprodução animal durante a organogénese não houve evidência de malformações do desenvolvimento.',
   E'FDA label (8.1): available data from a small number of post-marketing cases are insufficient to inform the risk; in animal reproduction studies during organogenesis there was no evidence of developmental malformations.',
   E'Dados insuficientes em grávidas; sem evidência de malformações em estudos animais.',
   E'Insufficient data in pregnant women; no evidence of malformations in animal studies.',
   E'Sem dados específicos sobre o aleitamento no rótulo (secção 8.2 não detalhada na extração).',
   E'No specific breastfeeding data in the label (section 8.2 not detailed in extraction).',
   E'Não aplicável (sem requisitos específicos de contraceção no rótulo).',
   E'Not applicable (no specific contraception requirements in the label).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Ertapenem (INVANZ), secção 8.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=33f3b99b-fa82-42e0-26bf-f49891ae3d22',
   'DailyMed/FDA (NIH/NLM) — approved Ertapenem label (INVANZ), section 8.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=33f3b99b-fa82-42e0-26bf-f49891ae3d22'),

  ('indacaterol', 'caution',
   E'Prontuário 5.1.1 (Agonistas adrenérgicos beta): o Anexo 1 (Gravidez) regista o indacaterol com fator de risco C (evitar) — o uso na gravidez deve ser ponderado; a broncodilatação beta-2 pode inibir as contracções uterinas (dados de classe).',
   E'Prontuário 5.1.1 (Beta adrenergic agonists): Annex 1 (Pregnancy) records indacaterol with risk factor C (avoid) — use in pregnancy should be weighed; beta-2 bronchodilation may inhibit uterine contractions (class data).',
   E'Fator de risco C (Anexo 1): evitar na gravidez; usar apenas se o benefício justificar o risco.',
   E'Risk factor C (Annex 1): avoid in pregnancy; use only if benefit justifies risk.',
   E'Anexo 2 (Aleitamento): há excreção do indacaterol no leite — ponderar a amamentação durante o tratamento (linha 42756 do Prontuário).',
   E'Annex 2 (Breastfeeding): indacaterol is excreted in milk — weigh breastfeeding during treatment (Prontuário line 42756).',
   E'Não documentada especificamente (sem requisitos no rótulo/Prontuário).',
   E'Not specifically documented (no requirements in the label/Prontuário).',
   'Prontuário Terapêutico do INFARMED (11.ª ed., 2012) — Anexo 1 (Gravidez), Anexo 2 (Aleitamento) e 5.1.1',
   'Prontuário Terapêutico do INFARMED (11th ed., 2012) — Annex 1 (Pregnancy), Annex 2 (Breastfeeding) and 5.1.1'),

  ('ivabradina', 'caution',
   E'Rótulo FDA (5.1/8.1): a ivabradina pode causar toxicidade fetal (dados animais — efeitos embrio-fetais e cardíacos teratogénicos em ratos a exposições 1-3× a dose humana máxima recomendada). Sem dados adequados em grávidas.',
   E'FDA label (5.1/8.1): ivabradine may cause fetal toxicity (animal data — embryo-fetal and cardiac teratogenic effects in rats at exposures 1-3× the maximum recommended human dose). No adequate data in pregnant women.',
   E'Risco de toxicidade fetal (dados animais); evitar na gravidez.',
   E'Risk of fetal toxicity (animal data); avoid in pregnancy.',
   E'Sem dados específicos sobre o aleitamento no rótulo (secção 8.2 não detalhada na extração).',
   E'No specific breastfeeding data in the label (section 8.2 not detailed in extraction).',
   E'Aconselhar mulheres em idade fértil a usar contraceção eficaz durante o tratamento (5.1).',
   E'Advise women of reproductive potential to use effective contraception during treatment (5.1).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Ivabradina (CORLANOR), secções 5.1/8.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=92018a65-38f6-45f7-91d4-a34921b81d0d',
   'DailyMed/FDA (NIH/NLM) — approved Ivabradine label (CORLANOR), sections 5.1/8.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=92018a65-38f6-45f7-91d4-a34921b81d0d'),

  ('levodopa', 'caution',
   E'Rótulo SINEMET (Pregnancy): sem estudos teratogénicos em ratos até 20× a dose humana máxima recomendada; malformações viscerais e esqueléticas em coelhos em todas as doses testadas; sem estudos adequados e bem controlados em grávidas.',
   E'SINEMET label (Pregnancy): no teratogenic effects in mice up to 20× the maximum recommended human dose; visceral and skeletal malformations in rabbits at all doses tested; no adequate and well-controlled studies in pregnant women.',
   E'Risco potencial (malformações em coelhos); usar apenas se o benefício justificar o risco.',
   E'Potential risk (malformations in rabbits); use only if benefit justifies risk.',
   E'Sem dados específicos sobre o aleitamento no rótulo; avaliar risco/benefício (a levodopa é excretada no leite humano — dados de literatura).',
   E'No specific breastfeeding data in the label; assess risk/benefit (levodopa is excreted in human milk — literature data).',
   E'Não aplicável (sem requisitos específicos de contraceção no rótulo).',
   E'Not applicable (no specific contraception requirements in the label).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Sinemet (ORGANON), secção Pregnancy: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9b17b028-964a-473c-823d-81423535bd66',
   'DailyMed/FDA (NIH/NLM) — approved Sinemet label (ORGANON), Pregnancy section: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9b17b028-964a-473c-823d-81423535bd66'),

  ('ticagrelor', 'caution',
   E'Rótulo FDA (8.1): dados de relatos de casos em grávidas não identificaram risco associado de malformações major, aborto ou desfechos maternos/fetais adversos; em ratos e coelhos, o ticagrelor causou anormalidades estruturais na descendência a doses maternas ~5-7× a dose máxima recomendada.',
   E'FDA label (8.1): case report data in pregnant women have not identified a drug-associated risk of major birth defects, miscarriage or adverse maternal/fetal outcomes; in rats and rabbits, ticagrelor caused structural abnormalities in offspring at maternal doses ~5-7× the maximum recommended dose.',
   E'Dados limitados em grávidas (casos pós-comercialização sem risco identificado); usar se o benefício justificar o risco.',
   E'Limited data in pregnant women (post-marketing cases without identified risk); use if benefit justifies risk.',
   E'Sem dados específicos sobre o aleitamento no rótulo (secção 8.2 não detalhada na extração).',
   E'No specific breastfeeding data in the label (section 8.2 not detailed in extraction).',
   E'Não aplicável (sem requisitos específicos de contraceção no rótulo).',
   E'Not applicable (no specific contraception requirements in the label).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Ticagrelor (BRILINTA), secção 8.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f7b3f443-e83d-4bf2-0e96-023448fed9a8',
   'DailyMed/FDA (NIH/NLM) — approved Ticagrelor label (BRILINTA), section 8.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f7b3f443-e83d-4bf2-0e96-023448fed9a8'),

  ('diltiazem', 'caution',
   E'Rótulo TIAZAC (Pregnancy): estudos de reprodução em ratos, murganhos e coelhos (4-6× o limite superior do intervalo ótimo, 480 mg/dia) com letalidade embrio-fetal e propensão para anomalias do esqueleto, coração, retina e língua; sem estudos bem controlados em grávidas — usar apenas se o benefício potencial justificar o risco.',
   E'TIAZAC label (Pregnancy): reproduction studies in mice, rats and rabbits (4-6× the upper limit of the optimum range, 480 mg/day) with embryo-fetal lethality and propensity for skeletal, heart, retina and tongue abnormalities; no well-controlled studies in pregnant women — use only if the potential benefit justifies the risk.',
   E'Usar apenas se o benefício potencial justificar o risco (letalidade embrio-fetal e anomalias em animais).',
   E'Use only if the potential benefit justifies the risk (embryo-fetal lethality and abnormalities in animals).',
   E'Sem dados específicos sobre o aleitamento no rótulo; avaliar risco/benefício.',
   E'No specific breastfeeding data in the label; assess risk/benefit.',
   E'Não aplicável (sem requisitos específicos de contraceção no rótulo).',
   E'Not applicable (no specific contraception requirements in the label).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Diltiazem (TIAZAC), secção Pregnancy: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c567fe7e-887e-4291-a0d1-2dd3f25cbf25',
   'DailyMed/FDA (NIH/NLM) — approved Diltiazem label (TIAZAC), Pregnancy section: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c567fe7e-887e-4291-a0d1-2dd3f25cbf25'),

  ('verapamilo', 'caution',
   E'Rótulo VERAPAMIL ER (Pregnancy): estudos de reprodução em coelhos e ratos (até 1,5× e 6× a dose oral diária humana) sem evidência de teratogenicidade; em ratos, a dose foi embriocida e atrasou o crescimento fetal; sem estudos adequados em grávidas — usar apenas se claramente necessário.',
   E'VERAPAMIL ER label (Pregnancy): reproduction studies in rabbits and rats (up to 1.5× and 6× the human oral daily dose) with no evidence of teratogenicity; in rats, the dose was embryocidal and retarded fetal growth; no adequate studies in pregnant women — use only if clearly needed.',
   E'Usar apenas se claramente necessário (sem teratogenicidade em animais, mas efeitos embriocidas em ratos).',
   E'Use only if clearly needed (no teratogenicity in animals, but embryocidal effects in rats).',
   E'Sem dados específicos sobre o aleitamento no rótulo; avaliar risco/benefício.',
   E'No specific breastfeeding data in the label; assess risk/benefit.',
   E'Não aplicável (sem requisitos específicos de contraceção no rótulo).',
   E'Not applicable (no specific contraception requirements in the label).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Verapamilo (NIVAGEN), secção Pregnancy: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e36e485f-fbed-4e30-9a63-984931f2e54e',
   'DailyMed/FDA (NIH/NLM) — approved Verapamil label (NIVAGEN), Pregnancy section: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e36e485f-fbed-4e30-9a63-984931f2e54e'),

  ('tacrolimus', 'caution',
   E'Rótulo PROGRAF (8.1): existe um registo de gravidez (Transplantation Pregnancy Registry International — TPRI) que monitoriza os resultados em recetoras de transplante expostas a imunossupressores; dados insuficientes para quantificar o risco.',
   E'PROGRAF label (8.1): there is a pregnancy registry (Transplantation Pregnancy Registry International — TPRI) that monitors outcomes in transplant recipients exposed to immunosuppressants; insufficient data to quantify the risk.',
   E'Risco potencial (imunossupressor, dados limitados); avaliar caso a caso com a equipa de transplante.',
   E'Potential risk (immunosuppressant, limited data); assess case by case with the transplant team.',
   E'Excretado no leite humano — recomenda-se não amamentar durante o tratamento (dados de literatura/8.2).',
   E'Excreted in human milk — breastfeeding during treatment is not recommended (literature data/8.2).',
   E'Discutir planeamento da gravidez e contraceção com recetoras de transplante em idade fértil.',
   E'Discuss pregnancy planning and contraception with transplant recipients of reproductive age.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Tacrolimus (PROGRAF), secção 8.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7f667de1-9dfa-4bd6-8ba0-15ee2d78873b',
   'DailyMed/FDA (NIH/NLM) — approved Tacrolimus label (PROGRAF), section 8.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7f667de1-9dfa-4bd6-8ba0-15ee2d78873b'),

  ('sirolimus', 'caution',
   E'Rótulo FDA (8.1): com base em estudos animais e no mecanismo de ação, o sirolimus pode causar dano fetal; dados limitados em grávidas, insuficientes para informar o risco de desfechos adversos do desenvolvimento.',
   E'FDA label (8.1): based on animal studies and the mechanism of action, sirolimus can cause fetal harm; limited data in pregnant women, insufficient to inform the risk of adverse developmental outcomes.',
   E'Pode causar dano fetal (dados animais + mecanismo); usar apenas se o benefício justificar o risco.',
   E'May cause fetal harm (animal data + mechanism); use only if benefit justifies risk.',
   E'Sem dados específicos sobre o aleitamento no rótulo; avaliar risco/benefício.',
   E'No specific breastfeeding data in the label; assess risk/benefit.',
   E'Não aplicável (sem requisitos específicos de contraceção no rótulo).',
   E'Not applicable (no specific contraception requirements in the label).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Sirolimus (MYLAN), secção 8.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5908cd1a-fc5a-462f-99ed-1d8983e253c9',
   'DailyMed/FDA (NIH/NLM) — approved Sirolimus label (MYLAN), section 8.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5908cd1a-fc5a-462f-99ed-1d8983e253c9'),

  ('micofenolato', 'contraindicated',
   E'Rótulo CELLCEPT (5.1/8.1): o uso de MMF na gravidez está associado a um risco aumentado de perda da gravidez no 1.º trimestre e de malformações congénitas múltiplas (ouvido externo e outras anomalias faciais, lábio/palato, membros distais, coração, esófago, rim e sistema nervoso). As mulheres em idade fértil devem ser aconselhadas sobre prevenção e planeamento da gravidez.',
   E'CELLCEPT label (5.1/8.1): use of MMF during pregnancy is associated with an increased risk of first-trimester pregnancy loss and of multiple congenital malformations (external ear and other facial abnormalities, cleft lip/palate, distal limbs, heart, oesophagus, kidney and nervous system). Women of reproductive potential must be counselled regarding pregnancy prevention and planning.',
   E'Evitar na gravidez se houver alternativas mais seguras; risco aumentado de perda no 1.º trimestre e malformações múltiplas (5.1).',
   E'Avoid in pregnancy if safer alternatives exist; increased risk of first-trimester loss and multiple malformations (5.1).',
   E'Sem dados específicos sobre o aleitamento no rótulo; avaliar risco/benefício (dados de literatura sugerem excreção).',
   E'No specific breastfeeding data in the label; assess risk/benefit (literature data suggest excretion).',
   E'Obrigatória a contraceção eficaz e teste de gravidez antes e durante o tratamento em mulheres em idade fértil (REMS — 5.1).',
   E'Effective contraception and pregnancy testing are mandatory before and during treatment in women of reproductive potential (REMS — 5.1).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Micofenolato (CELLCEPT), secções 5.1/8.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=37241e87-4af4-4dc3-a1aa-ea6f20d8dc40',
   'DailyMed/FDA (NIH/NLM) — approved Mycophenolate label (CELLCEPT), sections 5.1/8.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=37241e87-4af4-4dc3-a1aa-ea6f20d8dc40'),

  ('pimozida', 'caution',
   E'Rótulo FDA (PREGNANCY, Teratogenic Effects): estudos de reprodução em ratos e coelhos (até 8× a dose máxima humana) sem evidência de teratogenicidade; em ratos, a dose resultou em diminuição de gravidezes e desenvolvimento retardado dos fetos (inibição/atraso da implantação).',
   E'FDA label (PREGNANCY, Teratogenic Effects): reproduction studies in rats and rabbits (up to 8× the maximum human dose) with no evidence of teratogenicity; in rats, the dose resulted in decreased pregnancies and retarded fetal development (inhibition/delay of implantation).',
   E'Sem teratogenicidade em animais, mas com diminuição de gravidezes em ratos; usar apenas se o benefício justificar o risco.',
   E'No teratogenicity in animals, but decreased pregnancies in rats; use only if benefit justifies risk.',
   E'Sem dados específicos sobre o aleitamento no rótulo; avaliar risco/benefício.',
   E'No specific breastfeeding data in the label; assess risk/benefit.',
   E'Não aplicável (sem requisitos específicos de contraceção no rótulo).',
   E'Not applicable (no specific contraception requirements in the label).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Pimozida (ANI), secção PREGNANCY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4e954fc2-fdff-486c-beb6-2b8ace717081',
   'DailyMed/FDA (NIH/NLM) — approved Pimozide label (ANI), PREGNANCY section: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4e954fc2-fdff-486c-beb6-2b8ace717081')
) AS v(slug, pregnancy_category, risk_pt, risk_en, trimester_pt, trimester_en,
        lactation_pt, lactation_en, contraception_pt, contraception_en,
        source_pt, source_en)
ON d.slug = v.slug
ON CONFLICT (drug_id) DO NOTHING;

