SELECT d.id, v.condition_slug, v.condition_pt, v.condition_en, v.interaction_type, v.severity,
       v.reason_pt, v.reason_en, v.advice_pt, v.advice_en,
       v.source_pt, v.source_en, v.sort_order, 'published'
FROM public.drugs d
JOIN (VALUES
  -- Acenocumarol × gravidez (contraindicação — Prontuário 4.3.1.2)
  ('acenocumarol', 'gravidez', 'Gravidez', 'Pregnancy', 'contraindication', 'critical',
   E'Prontuário 4.3.1.2: os cumarínicos estão contraindicados durante o primeiro trimestre (são teratogénicos) e nas últimas semanas de gravidez (risco de hemorragia fetal ou placentar).',
   E'Prontuário 4.3.1.2: coumarins are contraindicated during the first trimester (teratogenic) and in the last weeks of pregnancy (risk of fetal or placental haemorrhage).',
   E'Contraindicado na gravidez; usar heparina quando é necessária anticoagulação.',
   E'Contraindicated in pregnancy; use heparin when anticoagulation is needed.',
   'Prontuário Terapêutico do INFARMED (11.ª ed., 2012) — 4.3.1.2', 'Prontuário Terapêutico do INFARMED (11th ed., 2012) — 4.3.1.2', 1),

  -- Acenocumarol × diátese hemorrágica / risco hemorrágico (contraindicação)
