  -- Diltiazem × doença do nó sinusal (contraindicação)
  ('diltiazem', 'doenca_no_sinusal', 'Doença do nó sinusal / distúrbios de condução', 'Sick sinus syndrome / conduction disorders', 'contraindication', 'critical',
   E'Rótulo TIAZAC (CONTRAINDICATIONS): contraindicado na síndrome do nó sinusal exceto na presença de pacemaker ventricular funcional, e no bloqueio AV de 2.º/3.º grau exceto com pacemaker funcional.',
   E'TIAZAC label (CONTRAINDICATIONS): contraindicated in sick sinus syndrome except in the presence of a functioning ventricular pacemaker, and in second-/third-degree AV block except with a functioning pacemaker.',
   E'Contraindicado em distúrbios de condução sem pacemaker; usar com precaução no bloqueio AV de 1.º grau.',
   E'Contraindicated in conduction disorders without a pacemaker; use with caution in first-degree AV block.',
   'DailyMed/FDA (NIH/NLM) — Diltiazem (TIAZAC), CONTRAINDICATIONS: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c567fe7e-887e-4291-a0d1-2dd3f25cbf25', 'DailyMed/FDA (NIH/NLM) — Diltiazem (TIAZAC), CONTRAINDICATIONS: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c567fe7e-887e-4291-a0d1-2dd3f25cbf25', 1),

  -- Diltiazem × hipotensão grave (contraindicação)
  ('diltiazem', 'hipotensao_nao_controlada', 'Hipotensão grave', 'Severe hypotension', 'contraindication', 'critical',
   E'Rótulo TIAZAC (CONTRAINDICATIONS): contraindicado em doentes com hipotensão grave (menos de 90 mmHg sistólicos).',
   E'TIAZAC label (CONTRAINDICATIONS): contraindicated in patients with severe hypotension (less than 90 mm Hg systolic).',
   E'Contraindicado em hipotensão grave (< 90 mmHg sistólicos).',
   E'Contraindicated in severe hypotension (< 90 mm Hg systolic).',
   'DailyMed/FDA (NIH/NLM) — Diltiazem (TIAZAC), CONTRAINDICATIONS: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c567fe7e-887e-4291-a0d1-2dd3f25cbf25', 'DailyMed/FDA (NIH/NLM) — Diltiazem (TIAZAC), CONTRAINDICATIONS: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c567fe7e-887e-4291-a0d1-2dd3f25cbf25', 2),

  -- Verapamilo × bloqueio AV grave (contraindicação)
  ('verapamilo', 'bloqueio_av', 'Bloqueio auriculoventricular', 'Atrioventricular block', 'contraindication', 'critical',
   E'Rótulo VERAPAMIL ER (CONTRAINDICATIONS): o verapamilo retarda a condução AV — contraindicado no bloqueio AV grave e na doença do nó sinusal; precaução no bloqueio AV de 1.º grau.',
   E'VERAPAMIL ER label (CONTRAINDICATIONS): verapamil slows AV conduction — contraindicated in severe AV block and sick sinus syndrome; caution in first-degree AV block.',
   E'Contraindicado no bloqueio AV grave e na doença do nó sinusal.',
   E'Contraindicated in severe AV block and sick sinus syndrome.',
   'DailyMed/FDA (NIH/NLM) — Verapamilo (NIVAGEN), CONTRAINDICATIONS: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e36e485f-fbed-4e30-9a63-984931f2e54e', 'DailyMed/FDA (NIH/NLM) — Verapamil (NIVAGEN), CONTRAINDICATIONS: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e36e485f-fbed-4e30-9a63-984931f2e54e', 1),

  -- Verapamilo × insuficiência cardíaca grave (contraindicação)
  ('verapamilo', 'insuficiencia_cardiaca', 'Insuficiência cardíaca', 'Heart failure', 'contraindication', 'critical',
   E'Rótulo VERAPAMIL ER (CONTRAINDICATIONS): contraindicado em doentes com insuficiência cardíaca grave ou disfunção ventricular esquerda grave (o efeito inotrópico negativo pode agravar a insuficiência cardíaca).',
   E'VERAPAMIL ER label (CONTRAINDICATIONS): contraindicated in patients with severe heart failure or severe left ventricular dysfunction (the negative inotropic effect may worsen heart failure).',
   E'Contraindicado na insuficiência cardíaca grave; usar com precaução na disfunção ventricular.',
   E'Contraindicated in severe heart failure; use with caution in ventricular dysfunction.',
   'DailyMed/FDA (NIH/NLM) — Verapamilo (NIVAGEN), CONTRAINDICATIONS: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e36e485f-fbed-4e30-9a63-984931f2e54e', 'DailyMed/FDA (NIH/NLM) — Verapamil (NIVAGEN), CONTRAINDICATIONS: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e36e485f-fbed-4e30-9a63-984931f2e54e', 2),

  -- Micofenolato × gravidez (contraindicação — embriotoxicidade)
  ('micofenolato', 'gravidez', 'Gravidez', 'Pregnancy', 'contraindication', 'critical',
   E'Rótulo CELLCEPT (5.1): o uso na gravidez está associado a risco aumentado de perda no 1.º trimestre e malformações congénitas múltiplas — evitar na gravidez se houver alternativas mais seguras.',
   E'CELLCEPT label (5.1): use in pregnancy is associated with increased risk of first-trimester loss and multiple congenital malformations — avoid in pregnancy if safer alternatives exist.',
   E'Evitar na gravidez; contraceção eficaz e teste de gravidez obrigatórios (REMS).',
   E'Avoid in pregnancy; effective contraception and pregnancy testing are mandatory (REMS).',
   'DailyMed/FDA (NIH/NLM) — Micofenolato (CELLCEPT), 5.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=37241e87-4af4-4dc3-a1aa-ea6f20d8dc40', 'DailyMed/FDA (NIH/NLM) — Mycophenolate (CELLCEPT), 5.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=37241e87-4af4-4dc3-a1aa-ea6f20d8dc40', 1),

  -- Pimozida × prolongamento QT (contraindicação)
  ('pimozida', 'prolongamento_qt', 'Prolongamento do intervalo QT', 'QT interval prolongation', 'contraindication', 'critical',
   E'Rótulo FDA (Drug Interactions): a pimozida prolonga o intervalo QT; o efeito aditivo é antecipado com outros fármacos que prolongam o QT (fenotiazinas, antidepressivos tricíclicos, antiarrítmicos classe Ia/III, macrólidos, moxifloxacina, mefloquina, tacrolimus, ziprasidona, entre outros) — não administrar com estes fármacos.',
   E'FDA label (Drug Interactions): pimozide prolongs the QT interval; an additive effect is anticipated with other QT-prolonging drugs (phenothiazines, tricyclic antidepressants, class Ia/III antiarrhythmics, macrolides, moxifloxacin, mefloquine, tacrolimus, ziprasidone, among others) — do not administer with these drugs.',
   E'Contraindicada com fármacos que prolongam o QT; monitorizar ECG, potássio e magnésio antes e durante o tratamento.',
   E'Contraindicated with QT-prolonging drugs; monitor ECG, potassium and magnesium before and during treatment.',
   'DailyMed/FDA (NIH/NLM) — Pimozida (ANI), Drug Interactions: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4e954fc2-fdff-486c-beb6-2b8ace717081', 'DailyMed/FDA (NIH/NLM) — Pimozide (ANI), Drug Interactions: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4e954fc2-fdff-486c-beb6-2b8ace717081', 1),

  -- Pimozida × síndrome QT congénito (contraindicação)
  ('pimozida', 'sindrome_qt_congenito', 'Síndrome QT congénito', 'Congenital long QT syndrome', 'contraindication', 'critical',
   E'Rótulo FDA (Drug Interactions/WARNINGS): a pimozida prolonga o intervalo QT — contraindicada em doentes com síndrome QT congénito ou com outros fatores que prolonguem o QT.',
   E'FDA label (Drug Interactions/WARNINGS): pimozide prolongs the QT interval — contraindicated in patients with congenital long QT syndrome or other QT-prolonging factors.',
   E'Contraindicada na síndrome QT congénito; monitorizar ECG antes e durante o tratamento.',
   E'Contraindicated in congenital long QT syndrome; monitor ECG before and during treatment.',
   'DailyMed/FDA (NIH/NLM) — Pimozida (ANI), Drug Interactions: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4e954fc2-fdff-486c-beb6-2b8ace717081', 'DailyMed/FDA (NIH/NLM) — Pimozide (ANI), Drug Interactions: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4e954fc2-fdff-486c-beb6-2b8ace717081', 2)
) AS v(slug, condition_slug, condition_pt, condition_en, interaction_type, severity,
        reason_pt, reason_en, advice_pt, advice_en,
        source_pt, source_en, sort_order)
ON d.slug = v.slug
ON CONFLICT (drug_id, condition_slug) DO NOTHING;

-- =====================================================================
-- 6. Alimentos (drug_food_interactions) — só as documentadas
-- =====================================================================
INSERT INTO public.drug_food_interactions
  (drug_id, entity_slug, entity_pt, entity_en, severity,
   mechanism_pt, mechanism_en, advice_pt, advice_en,
   source_pt, source_en, sort_order, status)
SELECT d.id, v.entity_slug, v.entity_pt, v.entity_en, v.severity,
       v.mechanism_pt, v.mechanism_en, v.advice_pt, v.advice_en,
       v.source_pt, v.source_en, v.sort_order, 'published'
FROM public.drugs d
JOIN (VALUES
  -- Dissulfiram × álcool (reação dissulfiram-álcool — qualquer fonte de etanol)
  ('dissulfiram', 'alcool', 'Álcool', 'Alcohol', 'critical',
   E'Rótulo FDA (WARNINGS): o consumo de álcool durante o tratamento com dissulfiram provoca a reação dissulfiram-álcool — rubor, taquicardia, hipotensão, náuseas e vómitos (acumulação de acetaldeído por inibição da aldeído desidrogenase). Reações graves e potencialmente fatais são possíveis; qualquer fonte de etanol (incl. bebidas, medicamentos com álcool, perfumes, vinagre) pode desencadear a reação.',
   E'FDA label (WARNINGS): alcohol consumption during disulfiram treatment causes the disulfiram-alcohol reaction — flushing, tachycardia, hypotension, nausea and vomiting (acetaldehyde accumulation from aldehyde dehydrogenase inhibition). Severe and potentially fatal reactions are possible; any source of ethanol (incl. beverages, alcohol-containing medicines, perfumes, vinegar) may trigger the reaction.',
   E'Instruir o doente a evitar qualquer fonte de álcool durante o tratamento (e nos dias após a suspensão); explicar os sintomas da reação e a procura de ajuda médica se grave.',
   E'Instruct the patient to avoid any source of alcohol during treatment (and in the days after discontinuation); explain the symptoms of the reaction and to seek medical help if severe.',
   'DailyMed/FDA (NIH/NLM) — Dissulfiram, WARNINGS: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b90f8ff4-4fb3-46ab-8149-cb55f24a4044', 'DailyMed/FDA (NIH/NLM) — Disulfiram, WARNINGS: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b90f8ff4-4fb3-46ab-8149-cb55f24a4044', 1),

  -- Ivabradina × sumo de toranja (inibidor moderado CYP3A4)
  ('ivabradina', 'sumo_toranja', 'Sumo de toranja', 'Grapefruit juice', 'moderate',
   E'Rótulo FDA (7.1): o sumo de toranja é um inibidor moderado do CYP3A4 — evite o uso concomitante (aumenta as concentrações de ivabradina, exacerbando bradicardia e perturbações de condução).',
   E'FDA label (7.1): grapefruit juice is a moderate CYP3A4 inhibitor — avoid concomitant use (it increases ivabradine concentrations, exacerbating bradycardia and conduction disturbances).',
   E'Evitar o sumo de toranja durante o tratamento.',
   E'Avoid grapefruit juice during treatment.',
   'DailyMed/FDA (NIH/NLM) — Ivabradina (CORLANOR), 7.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=92018a65-38f6-45f7-91d4-a34921b81d0d', 'DailyMed/FDA (NIH/NLM) — Ivabradine (CORLANOR), 7.1: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=92018a65-38f6-45f7-91d4-a34921b81d0d', 1),

  -- Levodopa × alimentos ricos em proteínas (competição de aminoácidos)
  ('levodopa', 'alimentos', 'Alimentos (refeições ricas em proteínas)', 'Food (protein-rich meals)', 'moderate',
   E'Rótulo SINEMET (Drug Interactions): as refeições ricas em proteínas podem reduzir a absorção da levodopa (competição com aminoácidos no transporte intestinal e na barreira hematoencefálica) — a resposta ao fármaco pode variar com o conteúdo proteico das refeições.',
   E'SINEMET label (Drug Interactions): protein-rich meals may reduce levodopa absorption (competition with amino acids at intestinal transport and the blood-brain barrier) — the response to the drug may vary with the protein content of meals.',
   E'Informar o doente sobre a possível variação da resposta com refeições ricas em proteínas; manter consistência nas refeições e ajustar a dose conforme a resposta clínica.',
   E'Inform the patient about possible response variation with protein-rich meals; keep meals consistent and adjust the dose according to clinical response.',
   'DailyMed/FDA (NIH/NLM) — Sinemet, Drug Interactions: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9b17b028-964a-473c-823d-81423535bd66', 'DailyMed/FDA (NIH/NLM) — Sinemet, Drug Interactions: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9b17b028-964a-473c-823d-81423535bd66', 1)
) AS v(slug, entity_slug, entity_pt, entity_en, severity,
        mechanism_pt, mechanism_en, advice_pt, advice_en,
        source_pt, source_en, sort_order)
ON d.slug = v.slug
ON CONFLICT (drug_id, entity_slug) DO NOTHING;
